// The handbook is rendered once from the same values used by the game.
function renderDocumentation() {
  const table = codexTable;
  const topics = new Map();
  const section = (id, title, content) => {
    const nestedContent = content.replace(/<(\/?)h([34])\b/g, (_, closing, level) => `<${closing}h${Number(level) + 1}`);
    topics.set(id, `<section class="codex-section" id="codex-${id}"><h3 class="codex-topic-heading">${escapeHtml(title)}</h3>${nestedContent}</section>`);
    return '';
  };
  const chapters = [
    { id: 'getting-started', title: 'Start und Kampfgrundlagen', topics: ['start', 'party', 'combat'] },
    { id: 'activities', title: 'Aktivitäten und Aufträge', topics: ['areas', 'deep-of-dark', 'tower', 'boss-challenge', 'offline', 'contracts', 'hunting-events', 'world-events'] },
    { id: 'loot-rules', title: 'Beute und Seltenheiten', topics: ['loot', 'powerups'] },
    { id: 'equipment', title: 'Ausrüstung und Upgrades', topics: ['inventory', 'gear', 'sockets', 'enchantments', 'glyphs'] },
    { id: 'progression', title: 'Charakterfortschritt', topics: ['economy', 'skilltree', 'pets'] },
    { id: 'trading-settings', title: 'Handel und Spielverwaltung', topics: ['market', 'settings'] },
  ];
  const percent = (value) => `${formatRuleNumber(value)} %`;
  const range = (values) => values ? values.map(formatRuleNumber).join('–') : '—';
  const combat = BALANCE.combat;
  const soulHarvest = COMPANION_SKILLS.healer.active.find(skill => skill.id === 'seelenernte');
  const loot = BALANCE.loot;
  const items = BALANCE.items;
  const deep = BALANCE.deepOfDark;
  const finalDeepDamage = areaEnemyBaseDamage(AREAS[AREAS.length - 1].id, deep.maxTier);
  const classes = Object.entries(CLASSES).map(([id, info]) => [
    info.label, info.role, CLASS_WEAPONS[id].map((slot) => SLOT_DATA[slot].label).join(', '), number(CLASS_DAMAGE[id]),
  ]);
  const skillTables = Object.entries(COMPANION_SKILLS).map(([id, skills]) => {
    const rows = ['passive', 'active'].flatMap(type => skills[type].map(skill => [
      skill.name, type === 'active' ? `Aktiv · Rang 1 · ${skill.cooldown} s Abklingzeit` : 'Passiv · Rang 10', skillDescription(skill),
    ]));
    return `<h4>${escapeHtml(CLASSES[id].label)}</h4>${table(['Fähigkeit', 'Typ / Basis-Abklingzeit', 'Wirkung'], rows)}`;
  }).join('');
  const regions = AREAS.map((area, index) => {
    const enemy = ENEMIES[area.id], skill = ENEMY_SKILLS[area.id];
    return [area.name, index === 0 ? 'Startgebiet' : 'Siege in allen vorherigen Gebieten der aktuellen Schwierigkeitsstufe',
      range(areaSoulRewardRange(area.id, 0)), `${enemy.name} · ${number(enemy.hp)} LP · ${number(enemy.damage)} Schaden vor Verteidigung`,
      `${skill.name}: jeder ${skill.attackInterval}. Gegnerangriff mit ${formatRuleNumber(skill.multiplier)}-fachem Schaden${skill.once ? ', nur einmal je Durchgang' : ''}`];
  });
  const baseRanges = [
    ...Object.keys(items.weaponBaseDamage).map((slot) => [slot, 'weaponDamage']),
    ...Object.keys(items.armorBaseDefense).map((slot) => [slot, 'armorDefense']),
  ].map(([slot, type]) => [`${SLOT_DATA[slot].label} · ${type === 'weaponDamage' ? 'Grundschaden' : 'Grundverteidigung'}`,
    ...RARITIES.map((rarity) => range(baseItemStatRange(slot, rarity.color, type)))]);
  const setTables = (definitions, totalPieces) => Object.entries(definitions).map(([name, set]) =>
    `<div class="codex-set"><h4 class="codex-set-heading">${escapeHtml(name)}<small>${escapeHtml(CLASSES[set.class]?.label || 'Alle Klassen')}</small></h4>${table(['Teile', 'Setbonus'], set.bonuses.map(bonus => [`${bonus.pieces}/${totalPieces}`, setBonusDescription(bonus)]))}</div>`).join('');
  const milestones = (items.armorUpgradeMilestones || []).map((bonus) => [`Alle vier Rüstungsteile mindestens +${bonus.level}`, setBonusDescription(bonus)]);
  const tierWeights = (weights) => {
    const total = Object.values(weights).reduce((sum, value) => sum + value, 0) || 1;
    return RARITIES.filter((rarity) => weights[rarity.color] > 0)
      .map((rarity) => `${rarity.name} ${percent(weights[rarity.color] / total * 100)}`).join(' · ');
  };
  const baseLoot = AREAS.map((area, index) => [area.name, tierWeights(rarityWeightsForAreaIndex(index,
    { mainClass: null, activeCompanion: null, deepOfDark: { tier: 0 } }))]);
  const deepRows = Array.from({ length: deep.maxTier + 1 }, (_, tier) => {
    return [difficultyName(tier), `${number(areaEnemyBaseHealth(AREAS[0].id, tier))}–${number(areaEnemyBaseHealth(AREAS[AREAS.length - 1].id, tier))} LP`,
      `${number(areaEnemyBaseDamage(AREAS[0].id, tier))}–${number(areaEnemyBaseDamage(AREAS[AREAS.length - 1].id, tier))} LP`,
      `${number(areaSoulRewardRange(AREAS[0].id, tier)[0])}–${number(areaSoulRewardRange(AREAS[AREAS.length - 1].id, tier)[1])}`, tier ? tierWeights(deep.rarityWeightsByTier[tier]) : 'Je Gebiet, siehe Beutetabelle'];
  });
  const attackRows = [...combat.attackSpeedTiers].reverse().map((tier, index, tiers) => [
    index === tiers.length - 1 ? `ab ${tier.minimumPercent} %` : `${tier.minimumPercent}–${tiers[index + 1].minimumPercent - 1} %`,
    `${tier.intervalTicks} Takte`, `${tier.intervalTicks * combat.tickMilliseconds} ms`,
  ]);
  const events = WORLD_EVENTS.flatMap((rarity) => rarity.effects.map((effect) => [rarity.rarity, `+${percent(effect.value)} ${effect.label}`]));
  const level = BALANCE.groupLevel, tree = BALANCE.skillTree;
  const introduction = `<div class="view-heading codex-heading">
      <div><p class="eyebrow">DAS WISSEN DER GRENZWACHT</p><h1>Spiel-<em>Kodex</em></h1>
      <p class="welcome-sub">Vom ersten Kampf bis zum fertigen Build: Regeln, Werte und Beutechancen.</p></div>
      <span class="codex-stamp">DARK RETURN<br><b>SPIELHANDBUCH</b></span>
    </div>
    <nav class="codex-index" id="codex-toc" aria-label="Inhaltsverzeichnis">
      <h2>Inhaltsverzeichnis</h2><ol class="codex-toc-list"></ol>
    </nav>
    ${section('start', 'Schnellstart', `
      <p>Wähle einen Namen, eine Hauptklasse und genau einen Gefährten aus einer anderen Klasse. Die Hauptklasse ist anschließend festgelegt. Du erhältst ${number(BALANCE.startingSouls)} Seelen, ${BALANCE.startingInventoryCapacity} Inventarplätze und eine gewöhnliche Klassenwaffe.</p>
      <ol>
        <li>Öffne das Inventar und lege die Startwaffe an: per Doppelklick oder durch Ziehen auf den Waffenslot.</li>
        <li>Wähle für Main und Gefährten je eine passive und eine aktive Fähigkeit.</li>
        <li>Starte im ersten Grenzgebiet. Siege öffnen die nächsten Gebiete und bringen Seelen sowie mögliche Ausrüstungsfunde.</li>
        <li>Hole Auftragsbelohnungen ab, rüste passende Funde aus und kaufe am Altar Stufen für beide Charaktere und ihre Begleittiere.</li>
      </ol>
      <p>Dein Fortschritt wird automatisch lokal gespeichert. Sichere ihn über <a href="#codex-settings">Einstellungen und Spielstand</a> regelmäßig als Datei.</p>`)}
    ${section('party', 'Klassen, Kampfgruppe und Fähigkeiten', `
      <p>Main und Gefährte haben eigene Lebenspunkte, Stufen, Ausrüstung und Talentpunkte. Nur diese beiden Klassen nehmen am Kampf teil. Du kannst den Gefährten wechseln; seine bisherigen Stufen, Fähigkeiten, Talente und Gegenstände bleiben erhalten. Ein laufender Kampf behält seine gestartete Besetzung.</p>
      ${table(['Klasse', 'Rolle', 'Erlaubte Waffen', 'Klassen-Grundschaden'], classes)}
      <p>Jede Klasse trägt Helm, Brust, Handschuhe, Schuhe, Amulett, zwei Ringe, zwei Ohrringe und drei Glyphen. Einen Schild in der Nebenhand darf nur der Krieger tragen. Rüstung und Schmuck ohne Klassenbindung sowie generische Sets sind klassenübergreifend verwendbar; Klassensets passen nur zu ihrer Klasse. Die Werte wirken auf den jeweiligen Träger. Beide Charaktere besitzen außerdem einen festen Begleittierplatz. Ein Heiler als Main erhält zusätzlich 12 % Lebenskraft.</p>
      <h3>Klassenfähigkeiten</h3>
      <p>Alle aktiven Fähigkeiten sind von Anfang an auf Basisrang 1 nutzbar. Im eigenen Klassenbaum werden sie verstärkt und spezialisiert. Jeder Charakter darf eine Passive lernen und eine aktive Fähigkeit ausrüsten. Passive wirken direkt aus dem Tree. Die Fähigkeiten-Seite bietet ausschließlich die aktive Auswahl. Aktive Fähigkeiten lassen sich manuell oder automatisch bei Bereitschaft einsetzen. Tote Charaktere wirken keine Fähigkeiten; direkte Heilungen werden erst bei fehlendem Gruppenleben eingesetzt.</p>
      <p>Die Tabellen zeigen Basis-Abklingzeiten. Abklingzeitreduktion verkürzt sie: Basiszeit × (1 − Reduktion / 100), höchstens ${combat.cooldownReductionCapPercent} % Reduktion.</p>
      ${skillTables}`)}
    ${section('combat', 'Kampfablauf und Schaden', `
      <p>Ein Kampftakt dauert ${combat.tickMilliseconds} ms. Gegner greifen alle ${combat.enemyAttackIntervalTicks} Takte an. Ein Gebietsdurchgang besteht aus drei Gegnern und gilt erst nach dem Sieg über alle als gewonnen. Siege führen automatisch zum nächsten Durchgang. Kämpfe können minimiert werden und laufen bei geöffneter Seite weiter; in inaktiven Tabs kann der Browser sie verlangsamen.</p>
      <p>„Kampf abbrechen“ beendet einen laufenden Durchgang sofort. Für einen noch nicht gewonnenen Durchgang gibt es keine Belohnung. Wird ein bereits erreichter Sieg gerade gutgeschrieben, wird dieser Abschluss noch beendet. Sind beide Gruppenmitglieder besiegt, bleibt die Sitzung offen: Nach ${formatRuleNumber(combat.defeatRecoveryMilliseconds / 1000)} Sekunden Erholung beginnt automatisch ein neuer Kampf mit voller Lebenskraft im selben Gebiet. Im Turm endet der Lauf dagegen bei Niederlage. Während der Erholung sind Angriffe und Fähigkeiten pausiert; Abbrechen bleibt möglich. Eine Niederlage gibt weder Siegbelohnungen noch Turmfortschritt. Ein neu gestarteter Kampf beginnt mit voller Lebenskraft.</p>
      <h3>Seelenernte</h3>
      <p>Der Heiler entzieht jedem lebenden Gegner einmal ${percent(soulHarvest.currentHealthPercent)} seines aktuellen Lebens, nicht seines maximalen Lebens. ${percent(soulHarvest.drainHealingPercent)} des tatsächlich entzogenen Lebens werden als Heilung gleichmäßig auf die lebenden Gruppenmitglieder verteilt. Überheilung verfällt; Gefallene werden nicht wiederbelebt. Der prozentuale Entzug erhält keine zusätzlichen Schadens-, Krit- oder Doppeltrefferboni; auch der Heilungsanteil bleibt fest. In der Bossprüfung gilt stattdessen normaler angriffsabhängiger Fähigkeitsschaden mit ${percent(soulHarvest.damageMultiplier * 100)} Grundschaden und den üblichen Schadensregeln. Die Grundabklingzeit beträgt ${formatRuleNumber(soulHarvest.cooldown)} s, bei maximaler Abklingzeitreduktion ${formatRuleNumber(soulHarvest.cooldown * (1 - combat.cooldownReductionCapPercent / 100))} s. Die Fähigkeit gewährt keine Unverwundbarkeit.</p>
      <h3>Zielwahl und Schutz der hinteren Reihe</h3>
      <p>Main und Gefährte verteilen ihre Einzelangriffe auf die lebenden Gegner; Flächenfähigkeiten treffen alle. Gegner bevorzugen lebende Krieger und Heiler. Solange einer von ihnen steht, sind Jäger und Magier als Ziele geschützt. Ein gewähltes Gegnerziel bleibt im Fokus, bis es fällt; danach wird neu gewählt. Seelenquell heilt den Heiler durch seinen tatsächlich verursachten Schaden; es erzwingt keine Gegnerzielwahl.</p>
      <h3>Treffer, kritische Treffer und Zusatzeffekte</h3>
      <p>Normale Angriffe können entsprechend der Trefferchance verfehlen. Aktive Schadensfähigkeiten und Schaden über Zeit benötigen keinen Trefferwurf. Der Schaden hängt von Klasse, eigener Stufe, Waffe, Angriffswert, Attributen und Boni ab und schwankt vor weiteren Multiplikatoren zwischen 82 % und 118 %.</p>
      <p>„Kritischer Schaden“ ist der gesamte Schadensmultiplikator eines kritischen Treffers: 200 % bedeutet doppelten Schaden. Kritische Chance hat kein künstliches Cap: Ab 100 % trifft jeder erfolgreiche Treffer kritisch; überschüssige Kritchance bringt normalerweise keinen weiteren Nutzen. Beim Jäger wandelt die Spezialisierung „Tödliche Präzision“ von Raubtierauge den Überschuss im Verhältnis 1:1 in zusätzlichen kritischen Schaden um. Auch aktive Fähigkeiten und Schaden über Zeit können kritisch treffen. „Chance auf zweiten Treffer“ und „Doppeltrefferchance“ werden addiert. Je volle 100 % gibt es einen sicheren Zusatztreffer; der Rest ist die Chance auf einen weiteren.</p>
      <p>Erneutes Anwenden von Brand oder Gift durch denselben Charakter auf dasselbe Ziel frischt die Laufzeit auf. Der bereits geplante nächste Schadenstick wird dabei nicht nach hinten verschoben; der Sekundentakt läuft weiter. Der Effekt stapelt sich dadurch nicht. Verzögert verarbeitete, fällige Ticks werden nachgeholt, solange Ziel und Verursacher leben. Der sofortige Treffer beim Wirken einer Brandfähigkeit bleibt erhalten.</p>
      <p>Bei allen vier Klassen hat eine erfolgreich eingesetzte Auto-Fähigkeit Vorrang vor dem normalen Angriff desselben Charakters. In diesem Takt entfällt sein Autohit. Auch ein manueller Fähigkeitseinsatz sperrt normale Angriffe für einen Kampftakt. Fähigkeiten mit eigener Ring-, Kettenblitz-, Brand- oder Bodenanimation erzeugen daneben kein zusätzliches Standardprojektil. Wird keine Fähigkeit eingesetzt, etwa wegen Abklingzeit oder weil keine Heilung nötig ist, kann ein nach Angriffstempo fälliger Autohit stattfinden. Laufende Brand- und Giftticks werden davon unabhängig verarbeitet.</p>
      <p>Doppeltrefferchance erzeugt zusätzliche einzelne Treffer bei normalen Angriffen, aktiven Schadensfähigkeiten und jedem Gift- oder Brandtick. Je volle 100 % entsteht ein garantierter Zusatztreffer; der Rest ist die Chance auf einen weiteren. Bei 101 % sind es insgesamt zwei sichere Treffer und mit 1 % Chance ein dritter; bei 301 % vier sichere und mit 1 % Chance ein fünfter. Bei Flächentreffern wird die Trefferanzahl einmal für alle Ziele bestimmt. Jeder Treffer würfelt Schaden und Krit unabhängig; normale Angriffe prüfen auch ihre Trefferchance einzeln. Trefferbasierte Effekte wie Lebensraub, Kritheilung und Gift-Auslösung werden je Treffer geprüft. Zusatztreffer landen im selben Angriffsmoment und treffen nur die ursprünglich gewählten, noch lebenden Ziele. Die Anzeige fasst pro Angriff und Ziel den Gesamtschaden zu einer Zahl zusammen; daneben steht × mit der Zahl der tatsächlich gelandeten Treffer. Trefferberechnung, Kritwürfe und Auslösungen bleiben einzeln. Der höchste Einzeltreffer zählt jeden Treffer separat. Heilungen, Buffs und die Kontrolleffekte der Fähigkeit werden nicht mehrfach ausgeführt. Das Magiertalent „Arkaner Doppelschlag“ gibt +20 % normale Doppeltrefferchance, keine zusätzliche Fähigkeitsausführung. Im Kampf und in der AFK-Schadensschätzung gilt insgesamt das Cap von ${formatRuleNumber(combat.extraAttackChanceCapPercent)} % Doppeltrefferchance, also maximal elf Treffer pro Angriff.</p>
      <p>Schadensboni werden in getrennten Kategorien berechnet: Angriff, kritischer Schaden, Schaden gegen verwundbare Ziele und Schaden über Zeit. Innerhalb jeder Kategorie werden die Boni addiert; erst die fertigen Kategorien werden miteinander multipliziert. Zum Angriffsbonus gehören passende Itemaffixe einschließlich Edelsteinen, Glyphen und dem eigenen Begleittier sowie gewöhnliche Angriffs- und Schadensboni aus Passiven, Sets, Talenten, Power-ups und Welt-Events. Drei Angriffsaffixe mit je 10 % ergeben deshalb insgesamt +30 % Angriff.</p>
      <p>Inventar → Werte zeigt unter Offensive den kombinierten multiplikativen Gesamtschadensbonus samt Faktor. Darin stecken Talente, ausgerüstete passive Schadensboni, eigene und Gruppen-Setboni, der Mythische Effekt sowie der Waffenlevel-100-Abschlussbonus. Beispielsweise ergibt zweimal +100 % zusammen +200 % bzw. ×3 Gesamtschaden. +25 % aus einem Set, +300 % aus einer mystischen Waffe, +50 % aus einer Passive und +100 % vom Waffenlevel ergeben zusammen +475 % bzw. ×5,75. Angriff, Attribute, der Waffenschadensbonus durch Waffenlevel, Krit, Verwundbarkeit, DoT-Bonus und Fähigkeitsgrundfaktor werden separat berechnet. Bedingte Boni auf multiplikativen Schaden, etwa Zwillingszorn, werden beim passenden Angriff derselben Summe hinzugefügt und stehen nicht dauerhaft im angezeigten Grundwert.</p>
      <p>Die Schadensbasis besteht aus Klassen-Grundschaden, zwei Punkten je zusätzlicher eigener Stufe, Waffengrundschaden und einem Fünftel des unmodifizierten Angriffswerts, abgerundet. Der Hauptattributfaktor erhöht diese Basis genau einmal. Anschließend wirken der gemeinsame Angriffsbonus, der Fähigkeitsfaktor und die jeweils zutreffenden Krit-, Verwundbarkeits- und DoT-Faktoren. Ausdrücklich Boni auf multiplikativen Schaden aus Fähigkeiten, Sets, Talenten und Waffen werden addiert und als ein gemeinsamer Faktor verrechnet. Der Angriffswert im Charakterfenster enthält den Angriffsbonus und die Attributskalierung bereits; er wird im Treffer nicht erneut skaliert.</p>
      <p>Verwundbare Gegner erleiden zunächst ${percent(combat.vulnerabilityBaseDamagePercent)} zusätzlichen Schaden; passende Werte und Setboni werden zu diesem Zusatz addiert. Verwundbarkeit betrifft die Gegnergruppe; erneutes Anwenden verlängert sie bis zum späteren Ablaufzeitpunkt. Gift und Brand werden vom Wert „Schaden über Zeit“ verstärkt. Erneutes Gift ersetzt das bisherige Gift auf dem Ziel; ein normaler Feuerball erneuert den Brand dieses Anwenders auf dem Ziel. Mit Brandmeister verursacht Feuerball sofortigen Schaden und profitiert nicht mehr vom DoT-Bonus; fällt der Anwender, endet auch sein fortlaufender Schaden. Einfrieren verhindert Angriffe des betroffenen Gegners; Betäubung verhindert die Angriffe der betroffenen Ziele. Stampfen betäubt ohne Erderschütterung nur sein Einzelziel und mit diesem Talent alle getroffenen Gegner. Der Boss kann nicht eingefroren werden.</p>
      <h3>Eingehender Schaden und Heilung</h3>
      <p>Heilfähigkeiten des Heilers erhalten pro Glaubenspunkt über dem Grundwert von ${number(BASE_STATS['Glaube'])} eine Heilverstärkung von ${percent(CLASS_ATTRIBUTE_SCALING.healer.healingPercentPerFaith)}. Diese verstärkt die Basisheilung relativ, statt sie direkt auf die geheilten Lebensprozente zu addieren. Buff- und Heileffektivität sowie passende Setboni wirken zusätzlich.</p>
      <p>Gegnerschaden ist ein fester Lebenspunktwert und hängt nicht von der maximalen Lebenskraft des getroffenen Helden ab. Gebiet, Schwierigkeitsstufe, Championstatus und gegnerische Fähigkeiten bestimmen den Ausgangsschaden; im Turm skaliert er mit der Turmrunde. Jeder Angriff schwankt um ±10 %. Verteidigung steigert die Schadensminderung mit abnehmendem Zuwachs und erreicht bei ${number(combat.defenseForDamageReductionCap)} Verteidigung die Grenze von ${combat.damageReductionCapPercent} %. Aktive Schutzfähigkeiten und passende Setboni reduzieren den verbleibenden Schaden; die gesamte Schadensminderung bleibt normalerweise auf ${combat.damageReductionCapPercent} % begrenzt. Ein nicht verhinderter Treffer verursacht nach Schadensminderung und Rundung mindestens ${number(combat.enemyMinimumHitDamage ?? 1)} Lebenspunkt Schaden. Ausweichen verhindert den Treffer vollständig. Ausweichboni aus Sets und Talenten werden für den jeweiligen Charakter addiert; jeder Gegnerangriff bekommt einen eigenen Ausweichwurf. Zusätzliches Leben und Ausdauer erhöhen damit die Anzahl überlebbarer Treffer.</p>
      <p>Nach einem Sieg werden 20 % der maximalen Lebenskraft wiederhergestellt; mit Heiler kommen 2 % und dessen gewählte Rastplatz-Passivboni hinzu. Besiegte Gruppenmitglieder werden mit diesem Anteil wiederbelebt. Normale Kampfheilung belebt nicht wieder. Änderungen der maximalen Lebenskraft durch Ausrüstung, Stufen oder Events erhalten im laufenden Kampf den bisherigen Lebensanteil und heilen nicht zusätzlich.</p>`)}
    ${section('areas', 'Grenzgebiete', `
      <p>Das erste Gebiet ist sofort offen. Für weitere Gebiete müssen alle vorherigen Gebiete auf der aktuellen Schwierigkeitsstufe gewonnen sein. Die Tabelle zeigt Basiswerte auf Gewöhnlich; Champions und höhere Schwierigkeiten erhöhen Gegnerleben und Schaden. Die Gruppenstufe kann zusätzlich das Gegnerleben erhöhen.</p>
      ${table(['Gebiet', 'Freischaltung', 'Basis-Seelen je Sieg', 'Gegnerbasis', 'Fähigkeit'], regions)}
      <p>Jeder ${loot.eliteEveryEncounters}. Durchgang einer Gebiets-Session ist ein Champion: ×${formatRuleNumber(loot.eliteHealthMultiplier)} Leben und ×${formatRuleNumber(loot.eliteDamageMultiplier)} Schaden. Die Zählung beginnt beim Start einer neuen Session erneut. Über dem internen Stufenbasiswert des Gebiets erhöht sich das Basisleben jedes Gegners je zusätzlicher Stufe um ${combat.enemyHealthPerLevelAboveRecommended}, zusätzlich zum Gebietsleben der gewählten Schwierigkeitsstufe.</p>
      <p>Der erste Sieg je Gebiet und Schwierigkeit gewährt zusätzlich ${number(loot.firstClearFarmBoxes)} Farm-Luckyboxen sowie ${number(loot.firstClearSoulsPerArea)} × Gebietsnummer (1–6) × Stufenfaktor Seelen. Die Faktoren für ${RARITIES.map(rarity => rarity.name).join(', ')} betragen ${Array.from({ length: deep.maxTier + 1 }, (_, tier) => Math.max(1, Math.min(loot.firstClearMaximumTierMultiplier, tier))).join(', ')}. Damit steigt auch die höchste Erstabschlussprämie nicht. Diese feste Prämie wird nicht durch Seelenboni erhöht. Champion-Zusatzseelen betragen ${loot.eliteSoulsMinimumBase} + ${loot.eliteSoulsMinimumPerLevel} × Gruppenstufe bis ${loot.eliteSoulsMaximumBase} + ${loot.eliteSoulsMaximumPerLevel} × Gruppenstufe.</p>`)}
    ${section('offline', 'AFK-Fortschritt in Gebieten und Turm', `
      <p>Ein gestarteter Gebietskampf aktiviert das AFK-Farmziel. Beim Schließen der Seite oder Ausblenden des Tabs wird der Gebietskampf pausiert. Beim Zurückkehren wird ausschließlich das gewählte Gebiet auf der gewählten Schwierigkeitsstufe mit ${formatRuleNumber(BALANCE.offlineProgress.efficiency * 100)} % Effizienz nachberechnet, maximal für die letzten ${BALANCE.offlineProgress.maximumHours} Stunden. Bei maximaler Abwesenheit entsprechen die ${BALANCE.offlineProgress.maximumHours} Stunden ungefähr ${formatRuleNumber(BALANCE.offlineProgress.maximumHours * BALANCE.offlineProgress.efficiency)} Stunden aktiver Farmzeit. Weitere Gebiete und Schwierigkeitsstufen werden offline nicht automatisch betreten. Auch ein gestarteter Turmlauf kann mit derselben Effizienz und Zeitgrenze offline fortgesetzt werden. Die Bossprüfung und automatische Zeitsteine sind nicht Teil dieses AFK-Modus.</p>
      <h3>Messung der Farmgeschwindigkeit</h3>
      <p>Die letzten bis zu ${BALANCE.offlineProgress.sampleLimit} vollständigen Runden liefern die Grundlage. Mindestens ${BALANCE.offlineProgress.minimumSamples} Messrunden sind nötig. Auch Runden ohne Auto-Fähigkeiten werden gemessen; Runden mit manuellen Fähigkeitseinsätzen werden nicht aufgenommen. Lange Runden von einer Minute oder mehr sind gültig. Kampfzeit, Siegpause und ${formatRuleNumber(combat.defeatRecoveryMilliseconds / 1000)} Sekunden Erholung bei Niederlagen fließen ein. Die Anzeige unter der Kampfüberschrift zeigt, ob AFK bereit ist. Änderungen an Build, Gruppe, Farmziel oder Kampfregeln erfordern neue Messungen. Waffenlevel setzen die Messreihe nicht zurück; ihr Schadenszuwachs wird in der Schätzung berücksichtigt. Reine Änderungen an Icons, Texten oder Effektdarstellungen verwerfen die Messungen nicht. Ohne ausreichende passende Messungen gibt es keine geschätzten Belohnungen.</p>
      <p>Das Ergebnis ist eine Schätzung aus den realen Runden, keine zweite tickgenaue Kampfsimulation. Das gemessene Verhältnis von Siegen und Niederlagen bleibt bestehen. Veränderte offensive Werte durch Waffenlevel, auslaufende Power-ups und wechselnde Welt-Events passen die geschätzte Kampfzeit an. Im Turm werden außerdem Gegnerleben und Schaden je Runde berücksichtigt; gemessene Lebensverluste und Heilung werden fortgeschrieben. Fehlen gemessene Gegnerangriffe, ergänzt eine Schätzung aus Verteidigung, Ausweichen und gewählten automatischen Heilfähigkeiten die Messung. Einzelne Krits, Betäubungen und Fähigkeitstakte werden dabei nicht einzeln simuliert.</p>
      <h3>Turmlauf fortsetzen</h3>
      <p>Im Turm reichen ebenfalls ${BALANCE.offlineProgress.minimumSamples} Messrunden. Passende Champion- und Archontmessungen werden bevorzugt; fehlen sie, werden vorhandene Runden auf das tatsächliche Gesamtleben und den Schaden des neuen Gegnertyps skaliert. Ohne ausreichende Messung kannst du den bestehenden Lauf bei der Rückkehr ohne neuen Tagesversuch weiterspielen.</p>
      <p>Die geschätzte Veränderung der Gruppen-Lebenskraft einschließlich der Heilung zwischen Runden wird fortgeschrieben. Eine Niederlage beendet den Lauf sofort. Es werden weder weitere Tagesversuche noch Zeitsteine automatisch eingesetzt. Bei einem erfolgreichen Offline-Abschnitt geht derselbe Lauf mit der nächsten Runde und der berechneten Lebenskraft weiter. Die gewählte Turmbeute, der dauerhafte Beutebonus durch besiegte Archonten und der Rundenrekord werden berücksichtigt. Auch diese Lebensberechnung ist eine Schätzung aus den gemessenen Runden.</p>
      <h3>Beute und Rückkehr</h3>
      <p>Jeder berechnete Sieg verwendet dieselben Regeln für Seelen, passende Ausrüstung, mystische Ausrüstung, Greater Affixe, Farmboxen und Lootfilter wie ein aktiver Gebietssieg. Die ${formatRuleNumber(BALANCE.offlineProgress.efficiency * 100)} % werden auf die Farmzeit angewendet, nicht nochmals auf die Belohnung. Waffen erhalten EP für berechnete Kills bis zum maximalen Waffenlevel. Inventar und Briefkasten werden verwendet; bei vollen Lagerplätzen kann Beute wie beim aktiven Farmen verloren gehen. Es gibt keine automatischen Käufe, Boxöffnungen oder Materialverbräuche.</p>
      <p>VIP und Power-ups zählen bei Seelen- und Dropboni nur bis zu ihrem jeweiligen Ablauf. Fehlende vergangene Welt-Events werden für die Berechnung im normalen 30-Minuten-Rhythmus zufällig nachgebildet. Zeitlich passende Kills können zum beim Zurückkehren aktuellen Jagdauftrag beitragen; alte Events werden nicht nachträglich abgeholt. Die Rückkehrübersicht und das Aktivitätsprotokoll zeigen Ergebnisse und verpasste Beute. Der Gebietskampf läuft danach minimiert weiter. „Kampf abbrechen“ beendet auch das AFK-Farmziel.</p>
      <p>Zeitpunkt und Belohnungen werden zusammen gespeichert, damit dieselbe Abwesenheit nicht mehrfach ausgezahlt wird. Laufende Runden werden beim Verlassen nicht als Sieg gezählt; bei der Rückkehr beginnt eine frische Runde. Der Spielstand bleibt lokal; eine manipulierte Geräteuhr oder Sicherung kann nicht serverseitig geprüft werden.</p>`)}
    ${section('tower', 'Turm des Namenlosen', `
      <p>Der Turm ist von Anfang an verfügbar und läuft endlos. Es gibt keine Turmstufe, Etagenwahl oder Fortsetzung auf einer gespeicherten Etage. Jeder neue Durchlauf beginnt bei Runde 1.</p>
      <p>Gegnerleben und Grundschaden wachsen ausschließlich mit der Turmrunde. Runde 1 beginnt mit den Gegnerwerten von ${escapeHtml(AREAS.find(area => area.id === combat.towerScaling.startArea).name)} auf Gewöhnlich. Runde ${number(combat.towerScaling.referenceRound)} erreicht die normalen Gegnerwerte von ${escapeHtml(AREAS.find(area => area.id === combat.towerScaling.targetArea).name)} auf ${difficultyName(combat.towerScaling.targetDeepTier)}. Danach steigt die Schwierigkeit mit derselben prozentualen Kurve weiter, ohne Plateau bei der Referenzrunde. Champion- und Bossfaktoren kommen zusätzlich hinzu.</p>
      ${table(['Turmrunde', 'Grund-Lebenskraft je Gegner', 'Grundschaden je Angriff vor Verteidigung'], [...new Set([1, Math.round(combat.towerScaling.referenceRound / 4), Math.round(combat.towerScaling.referenceRound / 2), combat.towerScaling.referenceRound, combat.towerScaling.referenceRound * 2])].map(round => { const values = towerEncounterStats(state, round); return [number(round), number(values.health), number(values.damage)]; }))}
      <p>Für Leben und Schaden gilt jeweils: Startwert × (Zielwert / Startwert)<sup>(Runde − 1) / (${combat.towerScaling.referenceRound} − 1)</sup>. Damit erhöht jede weitere Runde die Werte um denselben prozentualen Faktor. Die Referenzwerte stammen direkt aus den Gebietsregeln und übernehmen deren Änderungen automatisch. Im AFK-Turm werden Kampfzeit und erlittener Schaden an die höhere Runde angepasst; frühe Messungen gelten nicht unverändert für spätere Runden. Wenn bisher kein Gegnerangriff gemessen wurde, werden erstmals mögliche Angriffe anhand der aktuellen Turmrunde, Angriffshäufigkeit, Verteidigung und Ausweichchance geschätzt. Der Lauf stoppt deshalb nicht für eine zusätzliche Live-Messung. Noch nicht abgeschlossene Runden behalten ihre angerechnete Restzeit für die nächste Berechnung.</p>
      <p>Die Seelenbelohnung vor Boni bleibt stufenbasiert: Mit L als höchster Heldenstufe erhältst du ${formatRuleNumber(combat.towerSoulsMinimumBase)} + L × ${formatRuleNumber(combat.towerSoulsMinimumPerLevel)} bis ${formatRuleNumber(combat.towerSoulsMaximumBase)} + L × ${formatRuleNumber(combat.towerSoulsMaximumPerLevel)} Seelen je Sieg.</p>
      <p>Runden 5, 15, 25 usw. enthalten einen Champion; Runden 10, 20, 30 usw. den Archonten der Ketten als einzelnen Boss mit Kettenurteil. Dazwischen kämpfen drei Gegner. Ein Turm-Champion hat insgesamt das ${formatRuleNumber(3 * loot.eliteHealthMultiplier)}-Fache des Tabellenlebens eines normalen Gegners und ${formatRuleNumber(loot.eliteDamageMultiplier)}-fachen Grundschaden. Der Archont hat das 30-Fache des normalen Einzellebens; Kettenurteil verursacht jeden ${combat.towerSkillAttackInterval}. Angriff ${formatRuleNumber(combat.towerSkillMultiplier)}-fachen Grundschaden. Die drei Gegner einer normalen Runde haben jeweils den Tabellenwert; Champions erhalten ihre zusätzlichen Seelen ebenfalls anhand der höchsten Heldenstufe. Deine Heldenstufe, Ausrüstung und dein eigener Schwierigkeitsfortschritt verändern die Gegnerkurve nicht. Die Seelenbelohnungen richten sich weiterhin nach der höchsten Heldenstufe.</p>
      <p>Ein Versuch wird beim Start verbraucht, auch bei Abbruch oder Neuladen. Eine Niederlage beendet den Turmlauf; ein weiterer Lauf muss manuell gestartet werden und verbraucht einen neuen Versuch. Pro Tag gibt es ${BALANCE.dailyAttempts.tower} freie Turmläufe, mit VIP ${BALANCE.dailyAttempts.tower + BALANCE.dailyAttempts.vipBonus}. Die Tagesversuche erneuern sich um Mitternacht (${escapeHtml(BALANCE.dailyAttempts.timeZone)}); ungenutzte freie Versuche verfallen. Ein Turm-Zeitstein aus der Farm-Luckybox gewährt genau einen weiteren Lauf, wenn keine Versuche mehr vorhanden sind und kein Turmlauf aktiv ist. Ein ungenutzter Steinversuch bleibt beim Tageswechsel erhalten. Der Rekord der meisten gewonnenen Runden eines Durchlaufs wird dauerhaft gespeichert und ist über den Spielernamen in der Kopfzeile sichtbar. Ein Abbruch beendet den Durchlauf.</p>
      <p>Wähle auf der Turmseite eine Beuteart aus. Pro gewonnener Runde wird genau ein Wurf für diese Auswahl durchgeführt; Champions und Bosse verwenden dieselben Chancen. Die Auswahl wird gespeichert.</p>
      ${table(['Gewählte Beute', 'Basis-Chance pro Sieg'], loot.towerLootChoices.map(choice => [choice.label, percent(choice.chance)]))}
      <p>Die gewählte Turmbeute startet mit 25 % Basis-Chance. Jeder besiegte Archont erhöht sie dauerhaft um ${formatRuleNumber(loot.towerLootChancePerBoss)} %, ohne Obergrenze. Der Bonus gilt für alle Beutearten und bleibt über Turmläufe und Tageswechsel hinweg erhalten. AFK-Bosssiege zählen ebenfalls. Droprate-Power-up, Welt-Event und VIP wirken weiterhin relativ auf diese Basis-Chance; auch die effektive Chance kann über 100 % steigen. Je volle 100 % gibt es einen garantierten Gegenstand; der Rest ist die Chance auf einen weiteren. Bei 101 % erhältst du einen Gegenstand und mit 1 % Chance einen zweiten, bei 201 % zwei und mit 1 % Chance einen dritten. Edelsteine und Power-ups werden für jedes Exemplar einzeln gewürfelt. Der separate Farm-Luckybox-Wurf bleibt unverändert.</p>
      <p>Bei Erfolg erhältst du einen Gegenstand der gewählten Beuteart. Edelsteine fallen in allen fünf Seltenheiten aus ${GEM_PROFILES.length} gleich häufigen Attributprofilen. Die Seltenheit wird separat gewürfelt; die genauen Chancen und Werte stehen unter Sockel und Edelsteine. Powerups fallen direkt und gleichverteilt aus allen Powerup-Typen. Ausrüstung und Seltenheitssteine fallen nicht im Turm.</p>
      <p>Turmbelohnungen werden sofort gutgeschrieben. Im Aktivitätsprotokoll erscheint am Ende der Sitzung eine Zusammenfassung aller Seelen und Gegenstände einschließlich Farm-Luckyboxen. Nicht aufgenommene Beute wird darin getrennt ausgewiesen; einzelne Belohnungsmeldungen pro Runde entfallen.</p>`)}
    ${section('deep-of-dark', 'Schwierigkeitsstufen', `
      <p>Die sechs Schwierigkeitsstufen heißen ${RARITIES.map(rarity => rarity.name).join(', ')}. Nach Siegen in allen ${AREAS.length} Gebieten der aktuellen Stufe kannst du die nächste freischalten. Die Gebietssiege werden zurückgesetzt; beginne wieder im ersten Gebiet. Ausrüstung, Charakterstufen, Talente, Aufträge und Turmrekord bleiben erhalten. Bereits freigeschaltete Schwierigkeiten bleiben auf der Karte auswählbar.</p>
      <p>Auf der Karte kannst du bereits freigeschaltete niedrigere Stufen zum Farmen auswählen. Dort sind alle Gebiete offen, es gibt keinen erneuten Erstabschlussbonus und Siege öffnen keine Gebiete der aktuellen Stufe. Gegner, Seelen und Beute richten sich nach der gewählten Stufe.</p>
      <p>Gewöhnlich behält die bisherigen Gebiets-Basiswerte. Danach wachsen Leben und Schaden mit gleichmäßigen prozentualen Schritten pro Gebiet bis Mystisch, Gebiet ${AREAS.length}: ${number(deep.enemyHealthAtFinalArea)} LP und ${number(finalDeepDamage)} Grundschaden. Diese Endwerte bleiben unverändert. Championboni, Spezialangriffe und zusätzliches Leben durch die Gruppenstufe kommen hinzu. Schaden schwankt um ±10 % und wird durch Verteidigung reduziert. Bei ${combat.damageReductionCapPercent} % Schadensminderung bleiben am Endpunkt im Mittel ${number(finalDeepDamage * (1 - combat.damageReductionCapPercent / 100))} Schaden.</p>
      <p>Die Basis-Seelen steigen über alle sechs Stufen bis höchstens ${number(BALANCE.areaSouls.finalAreaMaximum)} pro Sieg im letzten Gebiet auf Mystisch. Damit bleibt der bisherige Höchstbetrag erhalten. Die Tabelle zeigt die Spannen vom ersten bis zum letzten Gebiet jeder Stufe. Seelenfund, Talente, Weltboni, VIP sowie Erstabschluss- und Championboni gelten weiterhin. Es gibt keinen zusätzlichen Schwierigkeitsmultiplikator auf Seelen.</p>
      <p>Die Namen bezeichnen die Schwierigkeit, nicht eine garantierte Beuteseltenheit. Gewöhnlich verwendet die gebietsabhängige Beutetabelle. Ungewöhnlich liefert beim normalen Ausrüstungswurf epische, Selten bis Mystisch legendäre Ausrüstung. Greater Affixe sind ab ${difficultyName(loot.greaterAffixMinimumDeepTier)} möglich; mystische Ausrüstung hat ab ${difficultyName(loot.mythicEquipment.minimumDeepTier)} ihren separaten Fundwurf.</p>
      ${table(['Stufe', 'Gegnerleben', 'Gegnerschaden vor Verteidigung', 'Seelen', 'Beute-Seltenheiten'], deepRows)}`)}
    ${section('boss-challenge', 'Bossprüfung', `
      <p>Ein Versuch dauert ${BALANCE.bossChallenge.durationSeconds} s; pro Tag gibt es ${BALANCE.dailyAttempts.boss} freie Versuche, mit VIP ${BALANCE.dailyAttempts.boss + BALANCE.dailyAttempts.vipBonus}. Die Tagesversuche erneuern sich um Mitternacht (${escapeHtml(BALANCE.dailyAttempts.timeZone)}); ungenutzte freie Versuche verfallen. Der Boss kann nicht besiegt werden und greift nicht an. Der verursachte Schaden bestimmt den Rang. Die farbige Stern-Medaille kennzeichnet die Rangstufen. Unterränge: ${[...new Set(BALANCE.bossChallenge.rankThresholds.map(rank => rank.tier))].map(tier => `${escapeHtml(tier)}: ${BALANCE.bossChallenge.rankThresholds.filter(rank => rank.tier === tier).length}`).join(' · ')}. Die mythische Stufe folgt auf Diamant und reicht von I bis X. Ab Mythisch VI benötigt jeder weitere Unterrang den zehnfachen Schaden des vorherigen. Im Kampf zeigt die Rangfortschrittsleiste den fehlenden Schaden bis zum nächsten Rang. Nach ${escapeHtml(BALANCE.bossChallenge.rankThresholds[BALANCE.bossChallenge.rankThresholds.length - 1].name)} ist der höchste Rang erreicht. Die Prüfung startet einmalig und führt anschließend nicht automatisch in die nächste Runde.</p>
      <p>Leere vor dem Start deinen Briefkasten. Pro erreichtem Subrang gibt es ${number(BALANCE.bossChallenge.soulsPerRank)} Seelen vor Welt-Event-, Seelentalent- und VIP-Bonus. Die Boxbelohnung wird pro Boxart separat berechnet: ${BALANCE.bossChallenge.luckyBoxesPerRank.join('–')} zufällige Boxen × Rangstufe × Subrang des höchsten in diesem Versuch erreichten Rangs. Bronze zählt als 1, Silber als 2, Gold als 3 usw.; Subrang I als 1, II als 2 usw. Beispiel: Gold III ergibt jeweils 9–27 Glyphen- und VIP-Luckyboxen. Es werden keine zusätzlichen Boxen für niedrigere Ränge addiert. Die Seelenbelohnung summiert alle in diesem Versuch erreichten Subränge. Wiederholte Ränge geben weiterhin Belohnungen. Unter dem ersten Rang gibt es keine Rangbelohnung. Dein höchster Rang und dein höchster Gesamtschaden bleiben gespeichert und werden auf der Bossstartseite angezeigt.</p>
      ${renderBossRankTable()}
      <p>Der Versuch wird beim Start verbraucht, auch bei Abbruch oder Neuladen. Zwischen Versuchen gibt es keine Abklingzeit. Wenn kein Versuch mehr vorhanden ist und kein Bosskampf aktiv ist, gewährt ein Boss-Zeitstein aus der Farm-Luckybox per Doppelklick im Inventar genau einen weiteren Versuch. Solange noch Versuche vorhanden sind, wird kein Stein verbraucht. Ein ungenutzter Steinversuch bleibt beim Tageswechsel erhalten. Mitten im laufenden Versuch aktiviertes oder auslaufendes VIP beendet den Kampf nicht.</p>`)}
    ${section('loot', 'Beute, Seltenheiten und Affixe', `
      <p>Jedes der sechs Gebietsmonster kann seinen eigenen Questgegenstand hinterlassen. Pro besiegtem Monster eines gewonnenen Gebietskampfs beträgt die Chance ${percent(QUEST_ITEM_RULES.dropChance * 100)}, auch bei Champions und AFK-Fortschritt. Dropratenboni verändern diese Chance nicht. Die Farbe entspricht der gespielten Schwierigkeit; die sechs Varianten werden getrennt gestapelt. Diese Gegenstände sind für künftige Quests vorgesehen, unveränderlich und unverkäuflich. Sie belegen keine Inventarplätze und haben den eigenen Inventarfilter „Questgegenstände“. Im Turm und in der Bossprüfung fallen sie nicht.</p>
      <p>Gebietssiege haben ${percent(loot.areaEquipmentDropChance * 100)} Basis-Ausrüstungs-Beutechance, Champions ${percent(loot.eliteEquipmentDropChance * 100)}. Dropratenboni aus Power-up und Welt-Event erhöhen diese Chancen relativ. Je erfolgreichem Beutewurf entsteht ein Gegenstand, nicht einer pro Gegner. Der Slot wird gleichverteilt aus den für die Kampfgruppe tragbaren Waffen-, Rüstungs- und Schmucktypen gewählt. Schmuck fällt erst ab Ungewöhnlich; bei gewöhnlicher Beute werden nur Waffen und Rüstung ausgewählt.</p>
      <p>Die Seltenheit richtet sich nach dem tatsächlich bekämpften Gebiet und der gewählten Schwierigkeitsstufe. Diese Tabelle zeigt Gewöhnlich ohne Talentbonus:</p>
      ${table(['Gebiet', 'Seltenheitschance'], baseLoot)}
      <h3>Seltenheiten und Affixe</h3>
      ${table(['Seltenheit', 'Zufällige Affixe'], RARITIES.map((rarity) => [rarity.name, items.affixCountByRarity[rarity.color] ?? 0]))}
      <p>Ausrüstungsteile können denselben zufälligen Affixtyp mehrfach erhalten, beispielsweise viermal kritischen Schaden bei vier Affixplätzen. Jeder Platz wird separat gewürfelt. Gleiche Affixtypen werden innerhalb ihrer Kategorie addiert; Lebenskraft- und Verteidigungsaffixe wirken dagegen weiterhin als einzelne Multiplikatoren. Die Affixspannen sind für alle Seltenheiten gleich. Werte werden gleichverteilt ganzzahlig gewürfelt; Aufwertungen werden anschließend angewendet. Feste Auftrags- und Glyphenboni können von diesen zufälligen Spannen abweichen.</p>
      <p>Greater Affixe können bei Gebietsfunden ab ${difficultyName(loot.greaterAffixMinimumDeepTier)} entstehen: Jeder zufällige Affix hat unabhängig ${percent(loot.greaterAffixChance * 100)} Chance. Mehrere Greater Affixe pro Gegenstand sind möglich. Bei gewöhnlicher bis legendärer Ausrüstung beträgt ihr Grundwert immer ${percent(loot.greaterAffixMaxMultiplier * 100)} des maximalen normalen Affixwerts, auch bei halben Punkten. Die Schmiede verstärkt ihn anschließend wie gewohnt. Auch zufällige Ausrüstungsangebote im Schwarzmarkt können ab der Greater-Freischaltung Greater Affixe besitzen. Normales Umprägen erzeugt keine neuen Greater Affixe. Im Tab Seltenheit erhöhen kann legendäre Ausrüstung ohne Greater Affix jedoch einmalig mit einem Seltenheitsstein einen zufälligen vorhandenen Affix zum Greater Affix aufwerten, unabhängig von der Schwierigkeit. Diese Nutzung bleibt auch nach dem Verlust des Greater Affixes verbraucht. Glyphen aus Glyphen-Luckyboxen können unabhängig von der freigeschalteten Schwierigkeitsstufe Greater Affixe erhalten; jeder ihrer beiden festen Boni hat unabhängig ${percent(loot.greaterAffixChance * 100)} Chance und wird auf ${percent(loot.greaterAffixMaxMultiplier * 100)} seines festen Grundwerts gesetzt. Aufträge vergeben keine legendäre Ausrüstung und keine garantierten Greater-Ausrüstungsgegenstände. Frühere Schwierigkeitsstufen bleiben auch nach der Greater-Freischaltung von Greater-Gebietsfunden ausgeschlossen. Ein Stern kennzeichnet sie im Inventar und Tooltip.</p>
      ${table(['Affix', 'Basis-Spanne'], Object.entries(AFFIX_RANGES).map(([stat, values]) => [stat, `${range(values)}${AFFIX_PERCENT_STATS.has(stat) ? ' %' : ''}`]))}
      ${table(['Ausrüstung', 'Mögliche Affixe'], [['Alle Waffen, Rüstungsteile und Schmuckstücke', [...new Set(Object.values(AFFIX_POOLS).flat())].join(', ')]])}
      <p>Gebietsdrops richten sich nach Main und aktivem Gefährten: Es fallen nur Waffen und Klassensets, die mindestens einer der beiden tragen kann. Schilde können nur mit einem Krieger in der Gruppe fallen. Generische Sets sowie allgemein tragbare Rüstung und Schmuck bleiben für jede Gruppe im Beutepool. Ein Wechsel des aktiven Gefährten passt die folgenden Drops entsprechend an.</p>
      <h3 class="rarity-mythic">Mystische Ausrüstung und Mythische Effekte</h3>
      <p>Ab ${difficultyName(loot.mythicEquipment.minimumDeepTier)} wird pro gewonnenem Gebietskampf einmal auf mystische Ausrüstung gewürfelt, auch bei Champions. Die Gesamtchance bleibt je Gebiet unverändert und erreicht ohne Boni maximal ${percent(Math.max(...loot.mythicEquipment.dropChanceByArea) * 100)}. Erst bei Erfolg wird gleichverteilt ein tragbarer Gegenstandstyp gewählt: Klassenwaffe, Schild, Rüstung, Schmuck oder Glyphe. Der mystische Fund ersetzt den normalen Ausrüstungsfund dieser Runde. Relative Dropratenboni aus Power-ups, Welt-Events und VIP wirken weiter. Rüstung und Schmuck können wie normale Gebietsbeute Sets angehören. Pets folgen ausschließlich ihrer eigenen Levelprogression.</p>
      ${table(['Gebiet', 'Mystisches Item pro Sieg (Basis)'], AREAS.map((area, index) => [area.name, percent(loot.mythicEquipment.dropChanceByArea[index] * 100)]))}
      <p>Mystische Waffen haben ${MYTHIC_ITEMS.weaponBaseDamageRange.map(number).join('–')} Grundschaden vor Aufwertungen. Mystische Rüstung und Schilde haben eigene höhere Grundwerte. Normale mystische Ausrüstung besitzt vier zufällige Affixe, mystische Glyphen behalten ihre zwei festen Glyphenboni. Alle vorhandenen Affixe sind garantiert Greater Affixe. Zufällige Affixe geben ${percent(loot.greaterAffixMaxMultiplier * 100)} ihres normalen Grundwurfs; feste Glyphenboni erhalten denselben Faktor. Mystische Ausrüstung kann alle zufälligen Affixplätze beliebig oft umprägen; Greater bleibt dabei erhalten. Die beiden festen Glyphenboni sind nicht umprägbar.</p>
      <p>Mystische Waffen erhalten je mystischer Stufe +${percent(MYTHIC_UPGRADES.damagePercentPerLevel)} multiplikativen Schaden, bis +${percent(MYTHIC_UPGRADES.damagePercentPerLevel * MYTHIC_UPGRADES.maxUpgradeLevel)} auf mystisch +${MYTHIC_UPGRADES.maxUpgradeLevel}. Alle anderen mystischen Teile einschließlich Glyphen geben vor mystisch +${MYTHIC_ITEMS.treeBonusUnlockLevel} keinen Mythischen Bonus. Ab dieser Stufe gibt jedes angelegte Teil +${MYTHIC_ITEMS.treeBonusRanks} Rang auf sämtliche Tree-Knoten des Trägers mit mindestens einem investierten Punkt. Mehrere Teile addieren sich. Auch Stat-Talente werden verstärkt; ungewählte Knoten, Freischaltungen, Punktkosten und die Grenzen für Passive und Spezialisierungen bleiben unverändert. Der Bonus kann effektive Ränge über das investierbare Maximum heben. Waffen geben keinen Tree-Bonus, andere Teile keinen mystischen Schadensbonus. Der Verkauf mystischer Ausrüstung gibt ${MYTHIC_ITEMS.saleStones} mystische Aufwertungssteine statt Seelen.</p>
      <h3>Grundschaden und Grundverteidigung</h3>
      <p>Die Seltenheit bestimmt auch diese Grundwertspannen. Mystische Klassenwaffen besitzen eine eigene Grundschadensspanne von ${MYTHIC_ITEMS.weaponBaseDamageRange.map(number).join('–')} vor Aufwertungen. Bei den übrigen Seltenheiten und gleicher Aufwertungsstufe liegt der niedrigste Grundwert einer höheren Seltenheit über dem höchsten Grundwert der vorherigen Seltenheit. Die Werte gelten vor Aufwertungen; Gegenstände haben keine zusätzliche Gegenstandsstufe.</p>
      ${table(['Gegenstand', ...RARITIES.map((rarity) => rarity.name)], baseRanges)}`)}
    ${section('inventory', 'Inventar, Briefkasten und Verkauf', `
      <p>Das Inventar ist gemeinsam. Wähle Main oder Gefährten, um passende Ausrüstung zu sehen und anzulegen. Materialien und Edelsteine bleiben für beide sichtbar. Filter und Sortierung ändern die Ansicht.</p>
      <p>Lege Gegenstände per Doppelklick oder durch Ziehen auf einen passenden Slot an. Ein Klick auf einen belegten Ausrüstungsslot legt ihn ab; dafür muss Inventarplatz frei sein. Ausgetauschte Teile gehen ins Inventar zurück.</p>
      <p>Beim Betrachten eines Ausrüstungstooltips erscheinen rechts daneben die angelegten Gegenstände derselben Plätze: bei Ringen und Ohrringen beide belegten Plätze, bei Glyphen bis zu drei. Im Inventar wird der ausgewählte Held verwendet. Passt ein Gegenstand nur zum anderen aktiven Helden, wird dessen Ausrüstung verglichen. Leere Plätze und der betrachtete Gegenstand selbst werden nicht doppelt angezeigt. Lange Vergleichsspalten lassen sich mit dem Mauszeiger im Tooltip scrollen.</p>
      <h3>Kapazität und Briefkasten</h3>
      <p>Nur Ausrüstung und Glyphen belegen Inventarplätze. Materialien, Edelsteine, Boxen, Power-ups sowie Boss- und Turm-Zeitsteine zählen nicht zur Kapazität; identische stapelbare Gegenstände werden zusammengefasst. Du hast von Anfang an fest ${BALANCE.inventory.maxCapacity} Inventarplätze.</p>
      <p>Passt eine Gegenstandsbelohnung nicht ins Inventar, geht sie in den Briefkasten mit maximal ${MAILBOX_CAPACITY} Einträgen. Hole sie über das Briefkastensymbol ab. Sind Inventar und Briefkasten voll, kann Kampfbeute verloren gehen; das Aktivitätslog nennt den verpassten Fund. Auftragsbelohnungen kannst du nach dem Freimachen von Platz erneut abholen.</p>
      <h3>Verkauf und Lootfilter</h3>
      <p>Verkaufen kannst du Waffen, Rüstung, Schmuck und Glyphen aus dem Inventar über den Schwarzmarkt. Materialien, Edelsteine, Verbrauchsgüter und Luckyboxen können nicht verkauft werden. Mystische Ausrüstung gibt statt Seelen je ${MYTHIC_ITEMS.saleStones} mystische Aufwertungssteine. Für andere Ausrüstung beträgt der Verkaufspreis 10 % des aktuellen Einkaufspreises der jeweiligen Seltenheit, auf ganze Seelen gerundet. Für legendäre Gegenstände mit mindestens einem Greater Affix gilt der entsprechende höhere Einkaufspreis. Aufwertungsstufe und Welt-Seelenboni verändern den Verkaufspreis nicht. Diese Preise gelten auch für den automatischen Verkauf durch den Lootfilter.</p>
      ${table(['Ausrüstung', 'Verkaufspreis in Seelen'], [...RARITIES.filter(rarity => rarity.color !== 'mythic').map((rarity) => [rarity.name, number(Math.round(EQUIPMENT_SHOP.prices[rarity.color] * 0.1))]), ['Legendär mit mindestens einem Greater Affix', number(Math.round(EQUIPMENT_SHOP.prices.legendaryGreater * 0.1))]])}
      <p>Im Bereich „Bisheriger Filter“ unter Einstellungen / Lootfilter markierst du Seltenheiten zum automatischen Verkauf. Dieser Filter gilt, solange die Sammelregeln deaktiviert sind. Mit „Nur ohne Set“ werden innerhalb der markierten Seltenheiten nur Gegenstände ohne Set verkauft. Nicht markierte Seltenheiten und Funde mit Greater Affixen werden immer behalten.</p>
      <p>Mit „Gezielt sammeln“ legst du stattdessen fest, welche Gebietsfunde behalten werden sollen. Innerhalb einer Sammelregel müssen Gegenstandstyp, Seltenheit, Setzugehörigkeit und die Mindestanzahl an Greater Affixen gemeinsam passen. Bei mehreren Regeln reicht eine passende Regel. Andere Ausrüstungsfunde werden automatisch verkauft, auch wenn sie Greater Affixe haben. Mythische Items werden mit aktiven Sammelregeln immer behalten.</p>
      <p>Sammelregeln und ihr Ein-/Ausschalter werden erst mit „Regeln speichern“ übernommen. Bis dahin bleibt der bisher gespeicherte Filter aktiv. Beide Filter betreffen nur neue Gebietsfunde, einschließlich AFK-Farmen, vor der Ablage und auch bei vollem Lager. Vorhandene Gegenstände, Käufe, Materialien und Auftragsbelohnungen bleiben unberührt. Behaltene Funde landen im Inventar oder bei Platzmangel im Briefkasten.</p>`)}
    ${section('gear', 'Schmiede, mystische Aufwertung und Sets', `
      <h3>Waffenlevel</h3>
      <p>Bogen, Schwert, Stab und Glocke besitzen unabhängig von ihrer Seltenheit ein eigenes Waffenlevel von 0 bis ${WEAPON_PROGRESSION.maxLevel}. Jeder besiegte Gegner in Gebieten und im Turm gibt den angelegten Waffen beider Kampfgruppenmitglieder ${WEAPON_PROGRESSION.experiencePerKill} EP, unabhängig vom letzten Treffer. Auch bereits besiegte Gegner einer abgebrochenen oder verlorenen Runde zählen. Die Bossprüfung gibt keine Waffen-EP. Championstatus, Schwierigkeitsstufe, VIP und Dropratenboni verändern die Waffen-EP nicht.</p>
      <p>Für den nächsten Rang benötigst du ${WEAPON_PROGRESSION.experienceStep} × (aktuelles Waffenlevel + 1) EP: Level 1 kostet ${WEAPON_PROGRESSION.experienceStep}, Level 2 weitere ${WEAPON_PROGRESSION.experienceStep * 2} EP. Insgesamt braucht Level ${WEAPON_PROGRESSION.maxLevel} ${number(weaponExperienceThreshold(WEAPON_PROGRESSION.maxLevel))} EP. Der Tooltip zeigt Waffenlevel, EP bis zum nächsten Level und den erhöhten Waffenschaden.</p>
      <p>Jedes Waffenlevel gibt +${WEAPON_PROGRESSION.damagePercentPerLevel} % Waffenschaden, innerhalb dieses Systems addiert. Auf Level ${WEAPON_PROGRESSION.maxLevel} sind das +${WEAPON_PROGRESSION.maxLevel * WEAPON_PROGRESSION.damagePercentPerLevel} % (&times;${formatRuleNumber(1 + WEAPON_PROGRESSION.maxLevel * WEAPON_PROGRESSION.damagePercentPerLevel / 100)}). Dieser Faktor erhöht ausschließlich den Schadensanteil der Waffe nach ihrer normalen Platz-Aufwertung, keine Attribute, Affixe oder sonstigen Schadensgrundwerte. Die anschließenden normalen Schadensmultiplikatoren wirken wie gewohnt. Beispiel ohne Platz-Aufwertung: 1.000 Waffenschaden werden auf Level 100 zu 6.000.</p>
      <p>Auf Waffenlevel ${WEAPON_PROGRESSION.maxLevel} kommt einmalig +${WEAPON_PROGRESSION.completionDamagePercent} % multiplikativer Gesamtschaden (&times;${formatRuleNumber(1 + WEAPON_PROGRESSION.completionDamagePercent / 100)}) hinzu. Dieser Abschlussbonus gilt für Angriffe, Schadensfähigkeiten und DoTs des Trägers, nicht für Heilung. Bei mystischen Waffen wirkt er zusätzlich zum separat aufgewerteten Mythischen Effekt.</p>
      <p>Level und EP gehören zur einzelnen Waffe. Ablegen, Wechseln zwischen Main und Gefährte sowie Umprägen oder Seltenheitserhöhung erhalten ihren Fortschritt. Eine andere Waffe am selben Platz übernimmt ihn nicht. Beim Verkauf geht die Waffe mitsamt ihrem Fortschritt verloren. Neue Waffen beginnen auf Level 0; Schilde besitzen kein Waffenlevel.</p>
      <h3>Schmiede</h3>
      <p>Für normale Ausrüstungsaufwertung, Sockeln und Verzauberung stehen nur aktuell angelegte Teile von Main und aktivem Gefährten zur Auswahl. Der Schmiede-Tab Glyphen kombinieren verwendet dagegen ausschließlich Glyphen aus dem Inventar. Aufwertung, geöffnete Sockel und eingesetzte Edelsteine gehören zum jeweiligen Ausrüstungsplatz und bleiben beim Wechsel oder Ablegen erhalten. Das abgelegte Teil erhält seine Werte ohne Platz-Aufwertung zurück. Main und jeder Gefährte sowie einzelne Ring-, Ohrring- und Glyphenplätze haben getrennte Fortschritte. Vorhandene Investitionen werden übernommen; ältere aufgewertete Inventarteile übertragen ihren Fortschritt beim nächsten Anlegen. Überzählige Edelsteine werden ins Inventar zurückgelegt.</p>
      <p>Alle Plätze einschließlich Waffen, Rüstung, Schmuck und Glyphen können bis +${items.maxUpgradeLevel} aufgewertet werden. Affixe erhalten pro Platzstufe +${formatRuleNumber(items.upgradeAffixPercentPerLevel)} % ihres Grundwerts: Grundwert × (1 + Platzstufe × ${formatRuleNumber(items.upgradeAffixPercentPerLevel)} / 100). Auf +10 entspricht das ×${formatRuleNumber(affixUpgradeMultiplier(10))}, auf +${items.maxUpgradeLevel} ×${formatRuleNumber(affixUpgradeMultiplier(items.maxUpgradeLevel))}. Waffengrundschaden und Grundverteidigung skalieren separat mit ${formatRuleNumber(items.upgradeBaseStatMultiplier)} je Stufe. Eingesetzte Edelsteine und gegenstandsspezifische Setboni werden dadurch nicht verstärkt.</p>
      <p>Materialien werden automatisch aus dem Inventar entnommen. Jeder Aufwertungsversuch verbraucht einen Stein; ein Fehlschlag lässt die Stufe unverändert. Einzelversuche werden sofort berechnet. Auto-Aufwertung verarbeitet alle nötigen Versuche sofort bis zur gewählten Zielstufe oder bis das Material aufgebraucht ist. Dies gilt auch für mystische Aufwertung und Auto-Sockeln. Auf dem Desktop zeigt das Ritual ein kurzes visuelles Feedback; es verzögert weder das Ergebnis noch die nächste Aktion. Unter Einstellungen / Spiel kannst du die Animationen abschalten. Auf Mobilgeräten erreichst du alle Bearbeitungen über den Item-Tooltip unter „Bearbeiten“, ohne separate Werkstattseiten.</p>
      ${table(['Versuch auf', 'Basis-Erfolgschance'], items.upgradeSuccessChanceByLevel.map((chance, index) => [`+${index + 1}`, percent(chance)]))}
      <h3 class="rarity-mythic">Mystische Aufwertung in der Schmiede</h3>
      <p>Im Tab „Mystische Aufwertung“ bearbeitest du angelegte mystische Waffen, Rüstung, Schilde, Schmuck und Glyphen. Jede erfolgreiche mystische Stufe verbraucht einen mystischen Aufwertungsstein; auch ein Fehlschlag verbraucht ihn. Bei Fehlschlag bleibt die Stufe erhalten. Waffen erhalten den Schadensbonus je Stufe; andere Teile schalten den Tree-Bonus erst auf mystisch +${MYTHIC_ITEMS.treeBonusUnlockLevel} frei. Normale Aufwertung und mystische Aufwertung sind getrennt verfügbar. Am Handy findest du beides im Bearbeitungsmenü des Item-Tooltips.</p>
      ${table(['Mystische Stufe', 'Mythischer Effekt', 'Basis-Erfolgschance zur nächsten Stufe'], Array.from({ length: MYTHIC_UPGRADES.maxUpgradeLevel + 1 }, (_, level) => [level, '+' + percent(level * MYTHIC_UPGRADES.damagePercentPerLevel), level < MYTHIC_UPGRADES.maxUpgradeLevel ? percent(MYTHIC_UPGRADES.successChanceByLevel[level]) : 'Maximum']))}
      <p>Normale und mystische Aufwertung sind unabhängig voneinander verfügbar, mobil beide unter „Bearbeiten“ am Item. Einzelversuche und Auto-Aufwertung erfolgen sofort; Auto endet am Ziel oder bei Materialmangel. Mystische Steine sind stapelbar, unverkäuflich und werden nicht im Schwarzmarkt angeboten.</p>
      <h3>Rüstungs- und Schmucksets</h3>
      <p>Rüstungssets zählen Helm, Brust, Handschuhe und Schuhe; Schmucksets zählen Amulett, zwei Ringe und zwei Ohrringe. Die Teile müssen zum selben Set gehören und auf einem Charakter getragen werden. Alle erreichten Setstufen werden kumuliert; Teile verschiedener Charaktere werden nicht zusammengezählt.</p>
      <p>Je Klasse gibt es ein gebundenes Rüstungs- und Schmuckset. Zusätzlich stehen generische Rüstungs- und Schmucksets für alle Klassen zur Verfügung. Feste Attributboni werden vor den prozentualen Setattributen und vor der Berechnung von Leben, Angriff und Heilwirkung angewendet. Prozentuale Boni derselben Art werden addiert; auch Boni auf multiplikativen Schaden aus Sets, Talenten, Schadenspassiven, mystischer Aufwertung und Waffenlevel werden addiert. Erst die Summe wird einmal auf den Schaden angewendet. Gruppenboni zählen vom Main und dem aktiven Gefährten, auch wenn der Träger im Kampf gefallen ist. Die Verwundbarkeit wird nur von lebenden Trägern ausgelöst und verkürzt keine länger laufende Verwundbarkeit.</p>
      <p>Heilungsboni verstärken vom Träger verursachte Heilung einschließlich der Seelenecho-Heilung; Rastplatzboni verstärken die eigene Erholung. Seelenecho heilt jedes lebende Gruppenmitglied um den angegebenen Anteil des tatsächlich entzogenen Gegnerlebens, auch bei Flächentreffern und Schaden über Zeit. Überzähliger Schaden zählt nicht, Überheilung verfällt, Gefallene werden dadurch nicht wiederbelebt. In der Bossprüfung zählt der gemessene Schaden.</p>
      <p>Setfähige Rüstung und Schmuck haben bei zufälliger Erzeugung immer ${percent(loot.areaSetDropChance * 100)} Setchance, unabhängig von Gebiet, Seltenheit oder Schwierigkeitsstufe. Das gilt auch für neue Ausrüstungsangebote im Schwarzmarkt. Bei Gebietsfunden wird die Setchance erst nach einem erfolgreichen Ausrüstungsfund geprüft. Der Setpool enthält die Sets der beiden aktiven Klassen und die generischen Sets. Die zwölf festen Auftragsgruppen vergeben generische und klassenbezogene Sets; ihre vollständigen Ziele und Belohnungen stehen unter „Reise und Aufträge“.</p>
      <h3>Rüstungssets</h3>
      <p>Schleierbund gewährt mit zwei Teilen +50 % Schaden über Zeit und mit drei Teilen +25 % Angriffsgeschwindigkeit. Vier Teile lassen direkte Treffer einen Schattennachhall am getroffenen Gegner hinterlassen: 30 % des ursprünglichen Schadens, verstärkt durch den eigenen DoT-Bonus, werden in drei Ticks über drei Sekunden verteilt. Jeder neue Treffer fügt einen eigenen Nachhall hinzu, ohne vorherigen Schaden zu überschreiben oder seine Ticks zu verschieben. Kritische Treffer und Doppeltreffer zählen bereits im Ursprungsschaden; der Nachhall würfelt sie nicht erneut und löst weder weitere Nachhalle noch Giftpfeile aus. Der DoT-Bonus wird beim Erzeugen des Nachhalls festgehalten. Schaden und Lebensraub werden dem verursachenden Charakter zugerechnet. Tote Ziele und der Wechsel in einen neuen Durchgang löschen offene Nachhalle; sie springen nicht auf andere Gegner über.</p>
      <p>Zwillingszorn gewährt mit zwei Teilen +50 % Doppeltrefferchance und mit drei Teilen weitere +50 %, insgesamt +100 %. Mit vier Teilen erhält jeder Treffer desselben Angriffs +10 % multiplikativen Schaden je ermitteltem Treffer: Zwei Treffer erhalten beide +20 % (×1,2), zehn Treffer alle +100 % (×2). Der normale Treffer zählt mit. Der Bonus wird für jeden Angriff neu berechnet und gilt auch für aktive Schadensfähigkeiten, Flächentreffer sowie Gift- und Brandticks. Bei Flächenangriffen zählt die gemeinsam ermittelte Trefferzahl, ohne zusätzliche Vervielfachung durch die Zahl der Ziele. Es gibt keinen über Angriffe hinweg angesammelten Schadensbonus.</p>
      ${setTables(ARMOR_SETS, 4)}
      <hr class="codex-set-divider">
      <h3 class="codex-set-group-heading">Schmucksets</h3>
      <p>Zeitweber gewährt mit zwei Teilen +25 % Abklingzeitreduktion und mit drei Teilen +10 % Trefferchance. Vier Teile speichern zusätzlich 30 % des tatsächlich verursachten Schadens als Zeitriss im getroffenen Gegner, ohne den ursprünglichen Schaden zu verringern. Stirbt er, wird sein gespeicherter Schaden sofort gleichmäßig auf die übrigen lebenden Gegner verteilt. Fünf Teile lassen den Zeitriss zusätzlich alle drei Sekunden aufbrechen; die Frist beginnt mit dem ersten gespeicherten Treffer und wird durch weitere Treffer nicht verschoben. Jeder Träger speichert seinen Schaden getrennt. Direkte Treffer, Fähigkeiten und eigener Schaden über Zeit einschließlich Schattennachhall laden den Riss auf, Herzverfall nicht. Ausbrüche erhalten keine erneuten Schadensboni und lösen weder Lebensraub noch weitere Treffer-Effekte oder neue Zeitrisse aus. Sie können vorhandene Risse getöteter Gegner auslösen. Ohne verbleibendes Ziel verfällt gespeicherter Schaden; er wird nicht in neue Durchgänge mitgenommen. Gefallene Träger verlieren ihre Risse. In der Bossprüfung wirken die zeitgesteuerten Ausbrüche regulär.</p>
      <p>Dämmerherz unterstützt Schaden über Zeit: Zwei Teile gewähren +50 % Schaden über Zeit, drei Teile +20 % Abklingzeitreduktion. Vier Teile heilen den Träger um 3 % seines tatsächlich verursachten DoT-Schadens; dazu zählt auch Schattennachhall. Mit fünf Teilen aktiviert eigener Brand, eigenes Gift oder eigener Schattennachhall Herzverfall: Das Ziel verliert pro Kampftick (0,3 s) zusätzlich 5 % seiner maximalen Lebenskraft, also bei durchgehender Wirkung rund 16,7 % pro Sekunde. Mehrere DoTs oder Träger stapeln diesen Lebensentzug nicht. Herzverfall erhält keine Schadensboni und löst weder Heilung noch kritische Treffer, Doppeltreffer oder weitere Effekte aus. In der Bossprüfung ist Herzverfall deaktiviert; die anderen Setboni bleiben aktiv. Gegen besiegbare Turmbosse wirkt er regulär.</p>
      ${setTables(JEWELRY_SETS, 5)}
      <h3>Rüstungsrang</h3>
      <p>Der niedrigste Aufwertungsrang deiner vier getragenen Rüstungsteile bestimmt den Rüstungsrang; gleiche Setnamen sind dafür nicht erforderlich. Es gilt nur die höchste erreichte Schwelle; diese Rangboni werden nicht untereinander addiert.</p>
      ${table(['Schwelle', 'Wirkung'], milestones)}`)}
    ${section('sockets', 'Sockel und Edelsteine', `
      <p>Waffen, Schilde und die vier Rüstungsteile können jeweils bis zu ${items.socketCounts.equipment} Sockel erhalten. Schmuck, Glyphen und Pets sind nicht sockelbar. Bereits eingesetzte Edelsteine aus Schmuck und Glyphen werden ins Inventar zurückgelegt. Es gibt einen gemeinsamen Edelsteintyp für alle Plätze. Jeder Öffnungsversuch verbraucht einen Sockelstein, auch bei Fehlschlag. Ein Fehlschlag lässt den Platz unverändert. Eine Mindestaufwertung ist nicht erforderlich.</p>
      ${table(['Sockel', 'Basis-Erfolgschance'], items.socketSuccessChanceByTarget.equipment.map((chance, index) => [index + 1, percent(chance)]))}
      <p>Wähle einen belegten Ausrüstungsplatz und öffne Sockel oder verwalte eingesetzte Edelsteine. Auf dem Desktop setzt du Edelsteine per Doppelklick oder Ziehen ein; mobil wählst du sie unter „Bearbeiten → Sockel & Edelsteine“ am Item. Entnehmen legt den Edelstein kostenlos ins Inventar zurück. Geöffnete Sockel und eingesetzte Edelsteine bleiben beim Ausrüstungswechsel am Platz. Alte Rüstungskristalle werden in universelle Edelsteine umgewandelt. Einzelversuche und Auto-Sockeln werden sofort berechnet; Auto endet bei der Zielanzahl oder Materialmangel. Auf dem Desktop läuft nur kurzes visuelles Feedback ohne Wartezeit.</p>
      <p>Die Auswahlbuttons oberhalb der Werkbank wechseln zwischen Sockelritual, Einsetzen und Edelsteinaufwertung. Beim Aufwerten werden jeweils ${items.gemUpgradeRatio} Edelsteine desselben Attributprofils und derselben Seltenheit aus dem Inventar zu einem Stein der nächsten Seltenheit. Das gelingt garantiert. „Alle möglichen“ führt die verfügbaren Aufwertungen dieser Stufe gesammelt durch; Restmengen bleiben erhalten. Eingesetzte Steine werden nicht verwendet. Legendär ist die höchste Stufe.</p>
      ${renderCodexGems()}`)}
    ${section('enchantments', 'Verzauberung', `
      <p>Seltenheitserhöhung und normales Umprägen funktionieren mit angelegter Ausrüstung von Main und aktivem Gefährten. Über „Begleittier“ lassen sich die Tiere beider Charaktere nach ihren eigenen Regeln umprägen. Seltenheit und umgeprägte Affixe bleiben Eigenschaften des Gegenstands und werden beim Austausch nicht übertragen. Der Fortschritt des Ausrüstungsplatzes bleibt erhalten. Die Auswahlbuttons oben neben dem Seitenicon wechseln zwischen Seltenheit, Ausrüstungsaffix und Begleittier.</p>
      <h3>Seltenheit erhöhen</h3>
      <p>Legendäre Ausrüstung einschließlich Glyphen kann im Verfahren „Zu Mystisch“ aufgewertet werden. Ihr Ausrüstungsplatz muss +${MYTHIC_ITEMS.ascension.requiredSlotLevel} erreicht haben. Jeder Versuch kostet ${MYTHIC_ITEMS.ascension.rarityStoneCost} Seltenheitssteine und ${MYTHIC_ITEMS.ascension.mythicStoneCost} mystische Aufwertungssteine. Die feste Erfolgschance beträgt ${percent(MYTHIC_ITEMS.ascension.successChance * 100)}; Boni auf Aufwertungschance erhöhen sie nicht. Beide Materialien werden auch bei Fehlschlag verbraucht. Das Item bleibt erhalten. Bei Erfolg bleiben ID, Set, Sockel und normale Slot-Aufwertung erhalten; die mystische Stufe beginnt auf +0 und alle bestehenden Affixe werden Greater Affixe.</p>
      <p>${escapeHtml(enchantmentRulesText('rarity'))} Die normale garantierte Erhöhung endet bei Legendär. Der eigene Versuch zu Mystisch wird separat angeboten. Der Aufwertungsmultiplikator wird auf die neuen Grundwerte und Affixe wieder angewendet.</p>
      <p>Die Vorschau zeigt vor dem Verbrauch den möglichen Grundschaden beziehungsweise die Grundverteidigung einschließlich Aufwertungen. Bei einem bisherigen Wertebereich bleibt die relative Position des Wurfs erhalten; bei einem festen bisherigen Grundwert wird im neuen Bereich zufällig gewürfelt. Beispiel: Ein gewöhnlicher Helm mit ${formatRuleNumber(baseItemStatRange('helmet', 'common', 'armorDefense')[0])} Grundverteidigung kann beim Wechsel auf Ungewöhnlich auf ${range(baseItemStatRange('helmet', 'uncommon', 'armorDefense'))} kommen.</p>
      <p>Doppeltrefferchance kann auf allen Waffen, Schilden, Rüstungsteilen und Schmuckstücken als Affix mit 5–10 % Grundwert vorkommen, auch beim Umprägen. Die Werte werden mit Setboni, Talenten und dem Power-up für zweite Treffer addiert. Greater Affixe und Aufwertungen verstärken den Grundwert wie gewohnt.</p><h3>Affix umprägen</h3><p>„Automatisch umprägen“ öffnet die Zielauswahl: Wähle einen Affixtyp und seinen Mindestwert einschließlich der aktuellen Aufwertung. Der Lauf prüft jeden Wurf und stoppt sofort beim Treffer, bei fehlenden Steinen für den nächsten Versuch oder über „Stoppen“. Ist das Ziel schon erfüllt, werden keine Steine verbraucht. Ausschlüsse und ihre Kosten gelten weiterhin; ausgeschlossene oder nicht erreichbare Ziele werden abgewiesen. Normale Ausrüstung behält die Bindung an einen einzigen umprägbaren Platz, mystische Ausrüstung behält ihre Greater Affixe. Umprägen hat auf Mobilgeräten und Desktop keine Animationswartezeit und ist auch während laufender Schmiede- oder Sockelaufträge möglich. Automatisches Umprägen läuft nur bei geöffnetem Spiel.</p>
      <p>Links neben dem Aktionsbutton öffnet „Affixe ausschließen“ eine Auswahl der unerwünschten Typen. Die Ausschlüsse werden getrennt für Ausrüstung und Begleittiere gespeichert und gelten für normale sowie mystische Ausrüstung. Pro Umprägung kosten 0 oder 1 zusätzliche Ausschlüsse 1 Stein, 2 Ausschlüsse 4 Steine, 3 Ausschlüsse 9 Steine usw.: maximal(1, Anzahl²). Der aktuell ersetzte Affixtyp ist bereits automatisch ausgeschlossen und wird nicht zusätzlich berechnet. Mindestens ein neuer Typ muss möglich bleiben. Popup und Werkbank zeigen Kosten sowie den aktuellen Vorrat; bei fehlenden Steinen ist keine Umprägung möglich. Die Kosten werden aus allen vorhandenen Stapeln bezahlt. Bei mystischer Ausrüstung kostet jeder Umprägungsversuch zusätzlich einen mystischen Aufwertungsstein, auch beim automatischen Umprägen. Fehlt eines der Materialien, findet kein Versuch statt. Seltenheitserhöhung und die einmalige Greater-Aufwertung bleiben bei einem Seltenheitsstein.</p>

      <p>${escapeHtml(enchantmentRulesText('affix'))} Auch weitere Versuche auf diesem Platz verbrauchen jeweils einen neuen Stein. Die übrigen Affixe bleiben unverändert. Eine Seltenheitserhöhung löst diese Bindung nicht.</p>`)}
    ${section('pets', 'Begleittiere', `
      <p>Main und Gefährte erhalten jeweils ihr eigenes fest gebundenes Begleittier auf Stufe 1. Jedes Tier hat ein eigenes Level und eigene Affixe. Seine Attribut- und Affixboni wirken ausschließlich auf seinen Besitzer. Das Tier belegt keinen Inventarplatz und kann nicht abgelegt, verkauft, geschmiedet oder gesockelt werden.</p>
      ${table(['Klasse des Besitzers', 'Begleittier', 'Bonus pro Tierstufe'], Object.entries(PET_RULES.byClass).map(([owner, pet]) => [CLASSES[owner].label, pet.name, '+' + number(PET_RULES.attributePerLevel) + ' ' + pet.stat]))}
      <p>Im Altar besitzt jedes Tier einen eigenen Tab. Jede Stufe kostet dieselben Seelen wie die entsprechende Heldenstufe. Bereits auf Stufe 1 wirkt der Attributbonus. Level und Affixe bleiben beim Wechsel des Gefährten erhalten. Das Tier beginnt in Gewöhnlich mit einem zufälligen Affix. Alle ${number(PET_RULES.affixEveryLevels)} Stufen steigt seine Seltenheit und es erhält einen weiteren Affix: ${RARITIES.map((rarity, index) => `${rarity.name} ab Stufe ${number(index ? index * PET_RULES.affixEveryLevels : 1)} (${index + 1} Affixe)`).join('; ')}. Ab Mystisch kommen keine weiteren Affixe hinzu; Basisattribute und die Werte der vorhandenen Affixe steigen weiterhin pro Stufe.</p>
      <p>Tieraffixe sind normale zufällige Würfe aus den Affixspannen und können keine Greater Affixe sein. Ihr Wert beträgt Grundwurf × (1 + Tierstufe × ${number(PET_RULES.affixPercentPerLevel)} / 100), auf zwei Nachkommastellen gerundet. Das Wachstum ist linear: Bei 1 % pro Stufe verdoppelt Stufe 100 den Grundwurf, Stufe 200 verdreifacht ihn. Auch neu freigeschaltete und umgeprägte Affixe erhalten sofort den Bonus der aktuellen Tierstufe. Auch gleiche Affixtypen sind mehrfach möglich. Im Verzauberer wählst du „Begleittier“, das Tier des Mains oder Gefährten und den gewünschten Affixplatz. Ohne zusätzliche Ausschlüsse kostet jeder Versuch einen Umprägungsstein und ersetzt den Typ durch einen anderen zufälligen Typ. Jeder Platz bleibt beliebig oft umprägbar; es gibt keine Bindung an einen einzigen Platz. Der neue Affix wird normal gewürfelt und erhält den aktuellen Tierlevelbonus.</p>
      <p>Mögliche Tieraffixe: ${PET_RULES.affixPool.map(escapeHtml).join(', ')}. Die Grundspannen stehen unter Beute, Seltenheiten und Affixe. Die Attributpunkte aus Tierleveln kommen vor prozentualen Attributboni hinzu; Affixe wirken zusätzlich.</p>`)}
    ${section('glyphs', 'Glyphen', `
      <p>Jeder Charakter hat drei Glyphenplätze. Glyphen sind für alle Klassen verwendbar, unabhängig vom Attribut ihres Namens. Mehrere Exemplare derselben Art dürfen gleichzeitig angelegt werden. Sie stammen aus der Glyphen-Luckybox oder dem Kombinieren dreier Inventarglyphen in der Schmiede und belegen im Inventar jeweils einen Platz.</p>
      ${table(['Glyphe', 'Feste Boni ohne Aufwertung'], GLYPH_DEFINITIONS.map((glyph) => [glyph.name, `+25 % ${glyph.bonusStat || 'Angriff'} und +100 ${glyph.stat}`]))}
      <p>Unabhängig von der freigeschalteten Schwierigkeitsstufe kann beim Öffnen einer Glyphen-Luckybox jeder Bonus unabhängig mit ${percent(loot.greaterAffixChance * 100)} Chance als Greater Affix entstehen. Sein Grundwert beträgt dann ${percent(loot.greaterAffixMaxMultiplier * 100)} des festen Normalwerts: ${formatRuleNumber(25 * loot.greaterAffixMaxMultiplier)} % Angriff beziehungsweise Lebenskraft und ${formatRuleNumber(100 * loot.greaterAffixMaxMultiplier)} Attributpunkte. Null, ein oder zwei Greater Affixe sind möglich; die Chance, überhaupt eine Glyphe aus der Box zu erhalten, bleibt unverändert. Die Schmiede verstärkt diese Grundwerte wie gewohnt.</p>
      <h3>Glyphen kombinieren</h3><p>Mit den Auswahlbuttons oben rechts wechselst du zwischen Aufwertung und Glyphen kombinieren. Wähle drei Glyphen aus deinem Inventar; gleiche und unterschiedliche Typen sind erlaubt. Ein erneuter Klick wählt eine Glyphe ab. Der Versuch verbraucht genau diese drei Exemplare und erzeugt garantiert eine neue zufällige Glyphe, gleichverteilt aus allen ${GLYPH_DEFINITIONS.length} Typen. Auch ein verwendeter Typ kann erneut entstehen. Angelegte Glyphen werden nicht verwendet. Weitere Materialien oder Seelen sind nicht erforderlich. Die neue Glyphe beginnt ohne Aufwertung und ohne Sockel. Ihre beiden festen Boni werden unabhängig von den Zutaten neu gewürfelt: je ${percent(loot.greaterAffixChance * 100)} Chance auf einen Greater Affix, ohne Schwierigkeitsvoraussetzung. Bestehende Greater Affixe werden weder garantiert noch übernommen. Das Kombinieren erfolgt auf Mobilgeräten und Desktop sofort. Mobil wählst du die beiden weiteren Glyphen direkt unter „Bearbeiten“ am Item; auf dem Desktop bleibt die Glyphenauswahl in der Schmiede mit kurzem, abschaltbarem Feedback.</p>
      <p>Die Boni gelten für den Träger; ein Attribut erhöht nur die für seine Klasse vorgesehenen Werte. Glyphenplätze lassen sich in der Schmiede aufwerten und bis zu ${items.socketCounts.equipment}-mal sockeln. Glyphen werden nicht in der Verzauberung umgeprägt.</p>`)}
    ${section('powerups', 'Power-ups', `
      <p>Ein Power-up gewährt seinem benannten Wert +10 % beziehungsweise bei additiven Prozentwerten +10 %. Es wirkt für beide aktiven Gruppenmitglieder und läuft 15 Minuten ab Aktivierung. Ein Doppelklick im Inventar verbraucht ein Exemplar.</p>
      <h3>Upgradechance</h3>
      <p>Das Upgradechance-Power-up gibt 15 Minuten lang +10 % relative Erfolgschance für normale Aufwertung, mystische Aufwertung und Sockelöffnen. Weitere Exemplare verlängern die Laufzeit; der Wert bleibt gleich. Es fällt aus denselben zufälligen Power-up-Pools wie die anderen Typen. Das epische Welt-Event gibt +10 %, das legendäre +20 % Upgradechance. Aktives VIP gibt zusätzlich +${percent(VIP_RULES.upgradeChancePercent)}. Die drei Quellen werden addiert und relativ auf die Basis-Chance angewendet: 1 % wird bei insgesamt +50 % zu 1,5 %, 80 % wird zu maximal 100 %. Die Werkstattmenüs zeigen die effektive Chance; die Tabellen im Kodex zeigen Basis-Chancen. Einzelversuche und Auto-Läufe verwenden dieselbe Berechnung. Materialkosten bleiben gleich, Fehlschläge verbrauchen weiterhin den Stein. Der Bonus verändert weder Verzauberung noch Affixwürfe, Glyphenkombinationen oder die Versuchsdauer.</p>
      <p>Das Droprate-Power-up gibt 15 Minuten lang +10 % relative Fundchance. Es fällt aus denselben zufälligen Power-up-Pools wie die anderen Typen. Die Welt-Events bieten zusätzlich +10 % Droprate in Episch und +20 % in Legendär. Power-up-, Event- und VIP-Dropratenbonus werden addiert. Aktives VIP gibt zusätzlich ${percent(VIP_RULES.dropRatePercent)}. Beispiel: Bei zusammen +30 % wird aus 50 % Basis-Chance eine Chance von 65 %. Der Bonus gilt jeweils einmal für die gesamte Gruppe und wirkt auf Gebietsausrüstung, gewählte Turmbeute und den separaten Farm-Luckybox-Drop, maximal bis 100 %. Er beeinflusst weder Boxinhalte noch Seltenheits-, Set- oder Greater-Affixwürfe, Erstabschlussprämien oder Seelenmengen.</p>
      <p>Gleiche Boni erhöhen ihre Stärke nicht weiter, sondern verlängern die verbleibende Laufzeit um je 15 Minuten. Unterschiedliche Werte können gleichzeitig aktiv sein. Die Power-up-Anzeige oben zeigt aktive Boni und Restzeiten; ein Klick aktiviert genau ein verfügbares Exemplar je Typ, nicht den ganzen Stapel.</p>
      <p>Power-ups fallen im Turm direkt mit der gewählten Beutechance. Sie stammen außerdem aus Farm-Luckyboxen sowie dem gemeinsamen Nietenpool von Glyphen- und VIP-Luckyboxen. Ihre Laufzeit richtet sich nach der Uhr und läuft auch bei geschlossener Seite weiter. Schaden, Heilung, Werteobergrenzen und Chance auf zweiten Treffer verwenden weiterhin ihre normalen Grenzen.</p>`)}
    ${section('economy', 'Charakterwerte, Stufen und Seelen', `
      <p>Jede Klasse steigt am Altar einzeln auf. Gruppenstufe ist der gerundete Durchschnitt von Main und Gefährte. Pro eigener Stufe steigen die Grundwerte um ${level.healthPerLevel} Lebenskraft, ${level.attackPerLevel} Angriff und ${level.defensePerLevel} Verteidigung. Die nächste Stufe kostet gerundet ${level.costBase} + ${level.costPerLevel} × aktuelle Stufe + ${level.costQuadratic} × aktuelle Stufe² Seelen. Bei mehreren Stufen werden die Einzelpreise aufeinanderfolgender Stufen addiert.</p>
      ${table(['Grundwert auf Stufe 1', 'Wert'], Object.entries(BASE_STATS).map(([stat, value]) => [stat, `${formatRuleNumber(value)}${STAT_PERCENT_STATS.has(stat) ? ' %' : ''}`]))}
      <p>Angriffsaffixe werden vor der Anwendung addiert. Affixe für Lebenskraft und Verteidigung multiplizieren den jeweiligen Wert weiterhin je Affix; die übrigen Prozentwerte werden addiert. Trefferchance ist auf 100 % begrenzt. Kritische Chance hat keine künstliche Obergrenze. Doppeltrefferchance ist insgesamt auf ${formatRuleNumber(combat.extraAttackChanceCapPercent)} % begrenzt, einschließlich aller Set-, Talent- und Power-up-Boni. Das ergibt maximal elf Treffer pro Angriff: einen Grundtreffer und zehn Zusatztreffer. Kritische Chance trifft ab 100 % immer kritisch; überschüssige Kritchance wird nur durch das Raubtierauge-Spezialisierung Tödliche Präzision weiter genutzt. Doppeltrefferchance gewährt dagegen je volle 100 % einen weiteren sicheren Treffer und für den Rest eine zusätzliche Trefferchance. Abklingzeitreduktion ist auf ${combat.cooldownReductionCapPercent} % begrenzt. Angriffsgeschwindigkeit endet bei ${combat.attackSpeedCapPercent} %.</p>
      ${table(['Angriffsgeschwindigkeit', 'Angriffsabstand', 'Zeit'], attackRows)}
      <p>Die Charakterwerte zeigen die vollständig erreichten Werte vor einer Begrenzung an. Sobald Trefferchance, Doppeltrefferchance, Angriffsgeschwindigkeit, Abklingzeitreduktion oder Schadensminderung ihr Cap erreichen oder überschreiten, erscheint es dahinter in Klammern, zum Beispiel 90 % (Cap: 75 %). Im Kampf wirkt weiterhin höchstens das Cap. Werte ohne festes Stat-Cap, etwa kritische Chance, erhalten keine zusätzliche Begrenzung durch diese Anzeige.</p>
      <h3>Klassenattribute</h3>
      <p>Die Skalierung zählt Attributpunkte über dem Grundwert. Glaube verstärkt beim Heiler aktive Heilung und vorhandene Schutzfähigkeiten mit prozentualer Schadensminderung; Buff- und Heileffektivität wird dazu addiert. Die Treffer des Heilers sind Schadensangriffe und keine automatische Heilung.</p>
      ${table(['Klasse', 'Angriff je zusätzlichem Attributpunkt', 'Leben je zusätzlicher Ausdauer', 'Heilwirkung je zusätzlichem Glaube'], Object.entries(CLASS_ATTRIBUTE_SCALING).map(([id, scaling]) => [CLASSES[id].label, scaling.damageAttribute ? `${percent(scaling.damagePercentPerPoint)} je ${scaling.damageAttribute}` : '—', scaling.healthPerStamina, percent(scaling.healingPercentPerFaith || 0)]))}
      <h3>Welche Seelenboni wo wirken</h3>
      <p>Bei Gebiets- und Turmsiegen werden die Seelenfundwerte beider Kämpfer addiert. Dieser Bonus, der höhere Seelentalentbonus, ein Welt-Seelenbonus und bei aktivem VIP der Faktor ${formatRuleNumber(1 + VIP_RULES.soulBonusPercent / 100)} wirken als getrennte Multiplikatoren. Die Basis-Gebietsseelen richten sich nach Gebiet und Schwierigkeitsstufe. Champion-Zusatzseelen werden vor Seelenfund, Talenten, Welt- und VIP-Bonus addiert. Die feste Erstabschlussprämie kommt erst danach hinzu und erhält keinen dieser Boni. Es gibt keinen zusätzlichen Schwierigkeitsmultiplikator auf Seelen.</p>
      ${table(['Quelle', 'Angewendete Boni'], [
        ['Gebietssieg samt Champion-Zusatz', 'Seelenfund beider Kämpfer × höheres Seelentalent × Welt-Event × VIP; Gebiet und Schwierigkeit bestimmen den Grundbetrag'],
        ['Erstabschlussprämie', 'Fester Betrag aus Gebietsnummer und Stufenfaktor, ohne weitere Seelenboni'],
        ['Turmsieg', 'Seelenfund beider Kämpfer × höheres Seelentalent × Welt-Event × VIP'],
        ['Bossprüfung', 'Höheres Seelentalent × Welt-Event × VIP; kein Seelenfund und kein Schwierigkeitsbonus'],
        ['Auftrags-Seelen', 'Welt-Event; kein Seelenfund, Seelentalent oder Schwierigkeitsbonus'],
        ['Verkauf', '10 % des Einkaufspreises ohne Seelenboni'],
        ['Direkte Seelen aus Luckyboxen', 'Ausgewürfelter Festbetrag ohne diese Boni'],
      ])}
      <p>Die Einträge mit „×“ bezeichnen Bonusfaktoren: 50 % Seelenfund ergibt den Faktor 1,5. Rundungen erfolgen während der Berechnung; die angezeigten Gebietsspannen enthalten nicht alle persönlichen Boni.</p>`)}
    ${section('skilltree', 'Klassenbäume und Skillpunkte', `
      <p>Jede Klasse besitzt ihren eigenen verzweigten Baum. Du kannst ausschließlich Knoten deiner Klasse lernen. Main und Gefährte haben getrennte Verteilungen und erhalten pro Charakterstufe einen Skillpunkt, bis maximal ${number(BALANCE.skillTree.maxPoints)} Punkte pro Charakter erreicht sind. Weitere Level geben keine zusätzlichen Skillpunkte. Talentknoten und Klassenfähigkeiten verwenden denselben Punktevorrat.</p>
      <p>Ein freier Weg beginnt im Zentrum. Gewöhnliche Knoten verbessern Attribute und Werte; größere Schlüsselknoten setzen stärkere Schwerpunkte. Pro Charakter ist nur ein Schlüsselknoten möglich. Die Verbindung und der jeweilige Vorgängerrang bestimmen, wann ein Folgeknoten verfügbar ist.</p>
      <h3>Passive und aktive Fähigkeiten</h3>
      <p>Du darfst genau eine passive Klassenfähigkeit lernen. Ihre zehn Ränge verstärken den Bonus; bereits Rang 1 von Giftpfeil besitzt den vollen angegebenen Giftschaden, während die Giftchance mit den Rängen wächst. Passive werden ausschließlich im Skilltree gelernt und wirken automatisch. Auf der Fähigkeiten-Seite wählst du eine der von Beginn an verfügbaren aktiven Fähigkeiten für den Kampf aus.</p>
      <p>Alle aktiven Fähigkeiten starten kostenlos auf Basisrang 1. Zehn zusätzliche Verstärkungen im Tree erhöhen sie bis Rang 11. Jeder investierte Punkt steigert Schadenswerte um 10 % ihres Grundwerts und Heilungswerte um 5 % ihres Grundwerts. Dauer und Grundabklingzeit bleiben gleich. Beispiel: 200 % Grundschaden werden nach zehn Verstärkungen zu 400 %. Rang- und Schadensboni sind unterschiedliche Berechnungsschritte.</p>
      <h3>Spezialisierungen</h3>
      <p>Nach zehn investierten Punkten im Grundknoten stehen zwei Subnodes bereit. Jede kostet einen Punkt. Du kannst immer nur eine der beiden Spezialisierungen derselben Fähigkeit wählen; diese Regel gilt auch für die passive Fähigkeit. Varianten verändern anschließend die Fähigkeit nach ihrer Beschreibung.</p>
      ${Object.entries(COMPANION_SKILLS).map(([owner, group]) => `<h4>${escapeHtml(CLASSES[owner].label)}</h4>${table(['Fähigkeit', 'Alternative 1', 'Alternative 2'], [...group.passive, ...group.active].map(skill => [skill.name, skill.variants[0].name + ': ' + skill.variants[0].description, skill.variants[1].name + ': ' + skill.variants[1].description]))}`).join('')}
      <p>Ein vollständiger Reset kostet ${number(BALANCE.skillTree.respecCost)} Seelen und gibt alle investierten Punkte dieses Charakters frei. Danach wird die Passive erneut im Klassenbaum gelernt. Aktive Fähigkeiten bleiben auf ihrem kostenlosen Basisrang verfügbar.</p>
      <p>Einzelne Knoten setzt du für ${number(BALANCE.skillTree.nodeRespecCost)} Seelen zurück. Dabei werden alle dort investierten Punkte und die Punkte abhängiger Knoten frei. Die betroffenen Knoten werden vorab angezeigt; andere Zweige bleiben erhalten.</p>`)}
    ${section('market', 'Schwarzmarkt und Luckyboxen', renderCodexMarket())}
    ${section('world-events', 'Welt-Events', `
      <p>Alle 30 Minuten wird zuerst eine Seltenheit gleichverteilt ausgewählt, dann einer ihrer Effekte. Genau ein Bonus ist aktiv und gilt für Main und Gefährte. Die Anzeige oben zeigt Bonus und Restzeit. Welt-Seelenboni gelten nur für die unter „Charakterwerte, Stufen und Seelen“ genannten Quellen.</p>
      ${table(['Seltenheit', 'Möglicher Bonus'], events)}`)}
    ${section('hunting-events', 'Jagdaufträge', `
      <p>Links neben den Welt-Events zeigt das Jagd-Event deinen Fortschritt und den Countdown bis zum nächsten Wechsel. Der spielinterne Tooltip nennt Zielgebiet, Schwierigkeitsstufe und Belohnungen. Er verlangt ${HUNTING_EVENT_RULES.targetKills} besiegte Monster in einem zufällig vorgegebenen Gebiet auf einer fest vorgegebenen Schwierigkeitsstufe. Es gibt genau einen Zähler; Kills in anderen Gebieten oder auf anderen Stufen zählen nicht. Turm und Bossprüfung zählen ebenfalls nicht.</p>
      <p>Eine Schwierigkeitsstufe kommt erst in den Zufallspool, nachdem du alle sechs ihrer Gebiete abgeschlossen hast. Frühere Stufen gelten nach dem Aufstieg weiterhin als abgeschlossen. Vor dem ersten vollständigen Durchlauf auf Gewöhnlich gibt es deshalb noch keinen Jagdauftrag. Bei einer neuen Jagd werden Gebiet und Stufe neu ausgewählt; dieselbe Kombination wird nicht unmittelbar wiederholt.</p>
      <p>Der Fortschritt wird beim Abschluss einer Kampfrunde gespeichert; bei Niederlage oder Abbruch zählen auch bereits besiegte Monster der angebrochenen Runde. Monster einer vor dem neuen Jagdauftrag begonnenen Runde werden nicht nachträglich für ihn angerechnet. Auftrag und Fortschritt bleiben innerhalb des laufenden Zeitfensters beim Neuladen erhalten. Nach Ablauf werden sie verworfen; es gibt keine separate Trophäe.</p>
      ${table(['Vorgegebene Stufe', 'Glyphen-Luckyboxen', 'VIP-Luckyboxen', 'Farm-Luckyboxen'], Array.from({ length: BALANCE.deepOfDark.maxTier + 1 }, (_, tier) => [difficultyName(tier), HUNTING_EVENT_RULES.rewards.glyphBox * (tier + 1), HUNTING_EVENT_RULES.rewards.vipBox * (tier + 1), HUNTING_EVENT_RULES.rewards.farmBox * (tier + 1)]))}
      <p>Nach ${HUNTING_EVENT_RULES.targetKills} Kills klickst du auf das Jagd-Div, um die versiegelten Boxen abzuholen. Alle ${HUNTING_EVENT_RULES.intervalSeconds / 60} Minuten startet automatisch ein neuer Auftrag, unabhängig vom bisherigen Fortschritt. Nicht abgeschlossene Aufträge und nicht abgeholte Belohnungen verfallen beim Wechsel. Nach frühem Abholen bleibt das Div sichtbar und zeigt die Restzeit bis zum festen Wechsel. Der Rhythmus wird gespeichert und läuft auch bei geschlossenem Spiel weiter; beim Öffnen beginnt nur das aktuelle Zeitfenster, ohne angesammelte Events oder Offline-Belohnungen. Die Belohnungsmengen sind fest; VIP, Dropratenboni und Welt-Events erhöhen sie nicht. Die Boxen verwenden beim Öffnen ihre normalen Gewinnchancen.</p>`)}
    ${section('contracts', 'Reise und Aufträge', renderCodexContracts())}
    ${section('settings', 'Einstellungen und Spielstand', `
      <h3>Gameplay, Lootfilter und Aufzeichnungen</h3>
      <p>„Auto-Fähigkeiten“ legt den Standard für neu gestartete Kämpfe fest; im laufenden Kampf kannst du Auto je Charakter umschalten. Kompakte Schadenszahlen ändern nur die Anzeige. Der Schalter "Werkstattanimationen" schaltet die Darstellungen in Schmiede, Sockelkammer und Verzauberung gemeinsam ein oder aus. Alle Bearbeitungen erfolgen sofort; die Animation ist rein visuell. Der Lootfilter bestimmt den automatischen Verkauf neuer Gebietsbeute.</p>
      <p>Das Aktivitätslog hält Belohnungen, Beutefunde, Käufe und Verkäufe, Handwerksergebnisse, Bossresultate, AFK-Ergebnisse und Farm-Zusammenfassungen fest. Turmbelohnungen werden am Sitzungsende zusammengefasst. Einzelne Helden- und Tierlevel, Talentpunkte, Ausrüstungs- und Fähigkeitswechsel, Kampfbeginn, Power-up-Aktivierungen, Edelsteinwechsel und Briefkastenabholungen werden nicht protokolliert. Automatisch durch den Lootfilter verkaufte Ausrüstung bleibt in der Statistik erfasst. Kurze Hinweise und Fehlermeldungen erscheinen am Bildschirm, ohne dauerhafte Einträge zu erzeugen. Wenn du den Mauszeiger über den Spielernamen bewegst, öffnet sich deine Statistik mit Spielzeit, besiegten Monstern, Schaden, Toden, Boxen und Ritualen.</p>
      <h3>Automatische Speicherung und Sicherungen</h3>
      <p>Dein Spielstand liegt lokal in diesem Browser für diese Website-Adresse. Es gibt kein Benutzerkonto und keine automatische Übertragung auf andere Browser. Gestartete Gebiets-Farmsitzungen und Turmläufe können bei der Rückkehr AFK-Fortschritt erhalten; die Regeln stehen unter AFK-Fortschritt in Gebieten und Turm. Power-up- und VIP-Laufzeiten, die Tagesversuche und der Erneuerungstimer der Schwarzmarktangebote laufen nach der Uhr weiter. Bosskämpfe und Auto-Werkstattläufe werden nach dem Neuladen nicht fortgesetzt; bereits gespeicherte Ergebnisse bleiben erhalten.</p>
      <p>Exportiere unter Einstellungen → Verwaltung eine JSON-Sicherung und bewahre sie außerhalb der Browserdaten auf. Ein Import prüft die Datei und ersetzt nach deiner Bestätigung den aktuellen Spielstand vollständig. Laufende Kämpfe und automatische Rituale werden dabei beendet; Spielstände werden nicht zusammengeführt.</p>
      <p>„Spielstand löschen“ setzt deinen lokalen Fortschritt nach Bestätigung zurück. Bereits exportierte Dateien auf deinem Rechner bleiben erhalten und können später importiert werden. Das Löschen von Browserdaten kann den Spielstand ebenfalls entfernen.</p>
      <p>Nutze für Änderungen am Spielstand möglichst einen Tab. Erkennt ein älterer Tab eine inzwischen neuere gespeicherte Version, werden seine Änderungen gestoppt. Bei einem Speicherkonflikt lädt die Seite den aktuellen Stand nach deiner Bestätigung neu; der ältere Stand wird nicht darübergeschrieben.</p>`)}`;
  return introduction + chapters.map(chapter => `<section class="codex-chapter" id="codex-chapter-${chapter.id}"><h2 class="codex-chapter-heading">${escapeHtml(chapter.title)}</h2>${chapter.topics.map(id => topics.get(id)).join('')}</section>`).join('');

}
